CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractFacilityVerticalMeasurement` (
  `id` BIGINT NOT NULL,
  `VerticalReferenceEntityID` STRING COMMENT 'This relationship identifies the entity (aka record) in which the VerticalReferenceID is found; It could be a different OSDU entity or a self-reference. For example, a Wellbore VerticalMeasurement may reference a member of a VerticalMeasurements[] array in its parent Well record. Alternatively, VerticalReferenceEntityID may be populated with the ID of its own Wellbore record to make explicit that VerticalReferenceID is intended to be found in this record, not another.',
  `EffectiveDateTime` TIMESTAMP COMMENT 'The date and time at which a vertical measurement instance becomes effective.',
  `VerticalMeasurementValue` DOUBLE COMMENT 'The value of the elevation or depth. Depth is positive downwards from a vertical reference or geodetic datum along a path, which can be vertical; elevation is positive upwards from a geodetic datum along a vertical path. Either can be negative.',
  `TerminationDateTime` TIMESTAMP COMMENT 'The date and time at which a vertical measurement instance is no longer in effect.',
  `VerticalReferenceID` STRING COMMENT 'The reference point from which the relative vertical measurement is made. This is only populated if the measurement has no VerticalCRSID specified. The value entered must match the VerticalMeasurementID for another vertical measurement array element in Wellbore or Well or in a related parent facility. The relationship should be  declared explicitly in VerticalReferenceEntityID. Any chain of measurements must ultimately resolve to a Vertical CRS. It is expected that a VerticalCRSID or a VerticalReferenceID is provided in a given vertical measurement array object, but not both.',
  `VerticalMeasurementDescription` STRING COMMENT 'Text which describes a vertical measurement in detail.',
  `master_data_Well_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Wellbore_id` BIGINT COMMENT 'Autocreated FK slot',
  `VerticalMeasurementTypeID_id` BIGINT COMMENT 'Specifies the type of vertical measurement (TD, Plugback, Kickoff, Drill Floor, Rotary Table...).',
  `VerticalMeasurementPathID_id` BIGINT COMMENT 'Specifies Measured Depth, True Vertical Depth, or Elevation.',
  `VerticalMeasurementSourceID_id` BIGINT COMMENT 'Specifies Driller vs Logger.',
  `WellboreTVDTrajectoryID_id` BIGINT COMMENT 'Specifies what directional survey or wellpath was used to calculate the TVD.',
  `VerticalMeasurementUnitOfMeasureID_id` BIGINT COMMENT 'The unit of measure for the vertical measurement. If a unit of measure and a vertical CRS are provided, the unit of measure provided is taken over the unit of measure from the CRS.',
  `VerticalCRSID_id` BIGINT COMMENT 'A vertical coordinate reference system defines the origin for height or depth values. It is expected that either VerticalCRSID or VerticalReferenceID reference is provided in a given vertical measurement array object, but not both.'
)
USING iceberg
COMMENT 'A location along a wellbore, _usually_ associated with some aspect of the drilling of the wellbore, but not with any intersecting _subsurface_ natural surfaces.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractFacilityVerticalMeasurement');

