  `id` BIGINT NOT NULL,
  `ValueType` STRING COMMENT 'The type of value to expect for this reference property, either "number" (floating point number), "integer",  "string", or "boolean".',
  `ValueCount` INT COMMENT 'The number of values in a tuple, e.g. For coordinates. The default is 1.',
  `RelationshipTargetKind` STRING COMMENT 'Only populated if ValueType=="string" and the values are expected to represent record ids, e.g. to a reference-data type, then this value holds the kind (optionally without the semantic version number).',
  `ColumnName` STRING COMMENT 'When describing a table column, e.g., in an associated dataset, this optional property allows the association of the record column definition(s) to dataset table column(s).',
  `abstract_AbstractColumnBasedTable_id` INT COMMENT 'Autocreated FK slot',
  `UnitOfMeasureID_id` INT COMMENT 'Only populated if the ValueType is "number". It holds the UnitOfMeasure associated with this reference property type. It is a relationship to a UnitOfMeasure record. If the UnitQuantityID and/or PropertyType.PropertyTypeID are populated in addition to UnitOfMeasureID, the referenced records must finally share the same dimension code. See Schema Usage Guide \'Unit of Measure Foundation\'.',
  `UnitQuantityID_id` INT COMMENT 'Only populated if the ValueType is "number". It holds the UnitQuantity associated with this reference property type. It is a relationship to UnitQuantity record. If `UnitQuantityID` is provided, `PropertyType` is expected to be omitted.',
  `PropertyType_id` INT COMMENT 'It holds the PropertyType associated with this reference property type, further defining the semantics of the value. It contains a relationship to PropertyType record and its (de-normalized) name. String or number values can represent e.g. A date or a time by referring to the respective PropertyType record id. If `PropertyType` is provided, `UnitQuantityID` is expected to be omitted.'
)
USING iceberg
COMMENT 'The purpose of this schema is best understood in the context of a columnar dataset: the AbstractReferencePropertyType describes a column in a columnar dataset by declaring its value type (number, string), a UnitQuantity if the value type is a number, a kind if the string value is actually a relationship to a e.g. reference-data type.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractReferencePropertyType');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractRemark` (
  `id` BIGINT NOT NULL,
  `RemarkSequenceNumber` INT COMMENT 'A unique identifier for each remark record. This identifier is used to uniquely identify a member in an array of remarks.',
  `Remark` STRING COMMENT 'A descriptive comment for this remark.',
  `RemarkSource` STRING COMMENT 'The person, vendor, interpreter or other provider of information.',
  `RemarkDate` TIMESTAMP COMMENT 'The date the remark was issued.',
  `work_product_component_WellLog_id` BIGINT COMMENT 'Autocreated FK slot'
)
USING iceberg
COMMENT 'A remark object, pairing a remark text with a source, e.g. an author, and a date, which is typically included in an array. The RemarkSequenceNumber acts as unique key in this case.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractRemark');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractSpatialLocation` (
  `id` BIGINT NOT NULL,
  `SpatialLocationCoordinatesDate` TIMESTAMP COMMENT 'Date when coordinates were measured or retrieved.',
  `CoordinateQualityCheckPerformedBy` STRING COMMENT 'The user who performed the Quality Check.',
  `CoordinateQualityCheckDateTime` TIMESTAMP COMMENT 'The date of the Quality Check.',
  `QuantitativeAccuracyBandID_id` INT COMMENT 'An approximate quantitative assessment of the quality of a location (accurate to > 500 m (i.e. not very accurate)), to < 1 m, etc.',
  `QualitativeSpatialAccuracyTypeID_id` INT COMMENT 'A qualitative description of the quality of a spatial location, e.g. unverifiable, not verified, basic validation.',
  `AsIngestedCoordinates_id` INT COMMENT 'The original or \'as ingested\' coordinates (Point, MultiPoint, LineString, MultiLineString, Polygon or MultiPolygon). The name \'AsIngestedCoordinates\' was chosen to contrast it to \'OriginalCoordinates\', which carries the uncertainty whether any coordinate operations took place before ingestion. In cases where the original CRS is different from the as-ingested CRS, the AppliedOperations can also contain the list of operations applied to the coordinate prior to ingestion. The data structure is similar to GeoJSON FeatureCollection, however in a CRS context explicitly defined within the AbstractAnyCrsFeatureCollection. The coordinate sequence follows GeoJSON standard, i.e. \'eastward/longitude\', \'northward/latitude\' {, \'upward/height\' unless overridden by an explicit direction in the AsIngestedCoordinates.VerticalCoordinateReferenceSystemID}.',
  `Wgs84Coordinates_id` INT COMMENT 'The normalized coordinates (Point, MultiPoint, LineString, MultiLineString, Polygon or MultiPolygon) based on WGS 84 (EPSG:4326 for 2-dimensional coordinates, EPSG:4326 + EPSG:5714 (MSL) for 3-dimensional coordinates). This derived coordinate representation is intended for global discoverability only. The schema of this substructure is identical to the GeoJSON FeatureCollection https://geojson.org/schema/FeatureCollection.json. The coordinate sequence follows GeoJSON standard, i.e. longitude, latitude {, height}',
  `SpatialParameterTypeID_id` INT COMMENT 'A type of spatial representation of an object, often general (e.g. an Outline, which could be applied to Field, Reservoir, Facility, etc.) or sometimes specific (e.g. Onshore Outline, State Offshore Outline, Federal Offshore Outline, 3 spatial representations that may be used by Countries).',
  `SpatialGeometryTypeID_id` INT COMMENT 'Indicates the expected look of the SpatialParameterType, e.g. Point, MultiPoint, LineString, MultiLineString, Polygon, MultiPolygon. The value constrains the type of geometries in the GeoJSON Wgs84Coordinates and AsIngestedCoordinates.'
)
USING iceberg
COMMENT 'A geographic object which can be described by a set of points.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractSpatialLocation');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractSpatialLocation_AppliedOperations` (
  `abstract_AbstractSpatialLocation_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `AppliedOperations` STRING NOT NULL COMMENT 'The audit trail of operations applied to the coordinates from the original state to the current state. The list may contain operations applied prior to ingestion as well as the operations applied to produce the Wgs84Coordinates. The text elements refer to ESRI style CRS and Transformation names, which may have to be translated to EPSG standard names.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractSpatialLocation_AppliedOperations');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractSpatialLocation_CoordinateQualityCheckRemarks` (
  `abstract_AbstractSpatialLocation_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `CoordinateQualityCheckRemarks` STRING NOT NULL COMMENT 'Freetext remarks on Quality Check.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractSpatialLocation_CoordinateQualityCheckRemarks');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTechnicalAssurance` (
  `id` BIGINT NOT NULL,
  `EffectiveDate` TIMESTAMP COMMENT 'Date when the technical assurance determination for this record has taken place',
  `Comment` STRING COMMENT 'Any additional context to support the determination of technical assurance',
  `master_data_Basin_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Field_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_GeoPoliticalEntity_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Organisation_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Rig_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_TubularAssembly_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_TubularComponent_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Well_id` BIGINT COMMENT 'Autocreated FK slot',
  `master_data_Wellbore_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_Document_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_PPFGDataset_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_WellLog_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreIntervalSet_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreMarkerSet_id` BIGINT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreTrajectory_id` BIGINT COMMENT 'Autocreated FK slot',
  `TechnicalAssuranceTypeID_id` BIGINT COMMENT 'Describes a record\'s overall suitability for general business consumption based on data quality. Clarifications: Since Certified is the highest classification of suitable quality, any further change or versioning of a Certified record should be carefully considered and justified. If a Technical Assurance value is not populated then one can assume the data has not been evaluated or its quality is unknown (=Unevaluated). Technical Assurance values are not intended to be used for the identification of a single "preferred" or "definitive" record by comparison with other records.'
)
USING iceberg
COMMENT 'Describes a record\'s overall suitability for general business consumption based on level of trust.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTechnicalAssurance');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTimeSeriesLink` (
  `id` BIGINT NOT NULL,
  `TimeIndex` INT COMMENT 'Index of the timestamp of the representation in the associated TimeSeries',
  `TimeSeriesID_id` BIGINT COMMENT 'Time series the representation is associated to'
)
