CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentBend` (
  `id` BIGINT NOT NULL,
  `BendAngle` DOUBLE COMMENT 'Bend Angle',
  `BendOffset` DOUBLE COMMENT 'Offset distance from the bottom connection to the bend'
)
USING iceberg
COMMENT 'Tubular Component Bend specific properties. Based on WITSML Tubular  Component \'Bend\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentBend');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentBitRecord` (
  `id` BIGINT NOT NULL,
  `NumBit` STRING COMMENT 'Bit number and rerun number e.g. "4.1" for the first rerun of bit 4.',
  `DiameterBit` DOUBLE COMMENT 'Diameter of drilled hole.',
  `DiameterPassThrough` DOUBLE COMMENT 'Minimum hole or tubing which bit will pass through (for bi-centre bits).',
  `DiameterPilot` DOUBLE COMMENT 'Diameter of pilot bit (for bi-centre bits).',
  `CostValue` DOUBLE COMMENT 'Bit cost in local currency.',
  `MfgCode` STRING COMMENT 'The manufacturer\'s code for the bit e.g. model number',
  `IADCCode` STRING COMMENT 'IADC bit code for PDC/Roller Cone Bits',
  `BitDullComments` STRING COMMENT 'Any other Bit Dull comments/description, older T-B-G code or full formatted dull grade e.g.  0-2-WT-N/S-X-I-LN-TD',
  `DriveType` STRING COMMENT 'Bit drive type (Motor, rotary table etc).',
  `BitClass` STRING COMMENT 'N = new, U = used.',
  `ReRunBitNumber` STRING COMMENT 'Re-run Bit Number to describe bit number when previously run',
  `HoursOnBit` DOUBLE COMMENT 'Cumulative Hours on Bit',
  `Remarks` STRING COMMENT 'Remarks',
  `TypeBitID_id` INT COMMENT 'Type of bit.',
  `InitialConditionInnerID_id` INT COMMENT 'As run bit IADC Dull Grade (I) Condition of Inner tooth rows (inner 2/3 of bit) (0-8).',
  `InitialConditionOuterID_id` INT COMMENT 'As run bit IADC Dull Grade (O) Condition of Outer tooth rows (outer 1/3 of bit) (0-8).',
  `InitialConditionDullID_id` INT COMMENT 'As run bit IADC Dull Grade (D) Overall dull condition from IADC bit wear 2 character codes.',
  `InitialConditionLocationID_id` INT COMMENT 'As run bit IADC Dull Grade (L) Location Row and cone numbers where wear located (e.g. Cracked Cone, Lost Cone etc).',
  `InitialConditionBearingID_id` INT COMMENT 'As run bit IADC Dull Grade (B) Condition of bit Bearings (integer 0-8 or E, F, N or X)).',
  `InitialConditionGaugeID_id` INT COMMENT 'As run bit IADC Dull Grade (G) Condition of bit Gauge in 1/16 of an inch. I = in gauge, else number of 16ths out of gauge.',
  `InitialConditionOtherID_id` INT COMMENT 'As run bit IADC Dull Grade (O) Other comments on bit condition from IADC list (BitDullCode in standard list).',
  `InitialConditionReasonID_id` INT COMMENT 'As run bit IADC Dull Grade (R) Reason bit was pulled',
  `FinalConditionInnerID_id` INT COMMENT 'Pulled bit IADC Dull Grade (I) Condition of Inner tooth rows (inner 2/3 of bit) (0-8).',
  `FinalConditionOuterID_id` INT COMMENT 'Pulled bit IADC Dull Grade (O) Condition of Outer tooth rows (outer 1/3 of bit) (0-8).',
  `FinalConditionDullID_id` INT COMMENT 'Pulled bit IADC Dull Grade (D) Overall Dull condition from IADC bit wear 2 character codes.',
  `FinalConditionLocationID_id` INT COMMENT 'Pulled bit IADC Dull Grade (L) Location Row and cone numbers where wear located (e.g. Cracked Cone, Lost Cone etc).',
  `FinalConditionBearingID_id` INT COMMENT 'Pulled bit IADC Dull Grade (B) Condition of bit Bearings (integer 0-8 or E, F, N or X).',
  `FinalConditionGaugeID_id` INT COMMENT 'Pulled bit IADC Dull Grade (G) Condition of bit Gauge in 1/16 of a inch. I = in gauge, else number of 16ths out of gauge.',
  `FinalConditionOtherID_id` INT COMMENT 'Pulled bit IADC Dull Grade (O) Other comments on bit condition.',
  `FinalConditionReasonID_id` INT COMMENT 'Pulled bit  IADC Dull Grade (R) Reason bit was pulled.',
  `HardAbrasiveFormationID_id` INT COMMENT 'Hard/Abrasive Formation'
)
USING iceberg
COMMENT 'Tubular Component Bit Record specific properties. Based on WITSML Tubular  Component \'BitRecord\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentBitRecord');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentConnection` (
  `id` BIGINT NOT NULL,
  `CXNOuterDiameter` DOUBLE COMMENT 'Outside diameter (OD) of the body of the connection.',
  `CXNInnerDiameter` DOUBLE COMMENT 'Inside diameter (ID) of the connection.',
  `OutsideConnectionLength` DOUBLE COMMENT 'External length of the connection.',
  `InsideConnectionLength` DOUBLE COMMENT 'Internal length of the connection.',
  `ThreadSize` DOUBLE COMMENT 'Thread size/diameter.',
  `YieldStress` DOUBLE COMMENT 'Tensile yield stress of the connection',
  `YieldTorque` DOUBLE COMMENT 'Torque limit for the connection',
  `CriticalCrossSectionArea` DOUBLE COMMENT 'Critical Cross Section Area (for bending stiffness ratio).',
  `LeakPressure` DOUBLE COMMENT 'Leak Pressure',
  `MakeUpTorque` DOUBLE COMMENT 'Make Up Torque',
  `master_data_TubularComponent_id` INT COMMENT 'Autocreated FK slot',
  `ThreadTypeID_id` INT COMMENT 'Thread/Connection Type',
  `PositionID_id` INT COMMENT 'Position of connection'
)
USING iceberg
COMMENT 'Tubular Connection specific properties. Based on WITSML Tubular  Component \'Connection\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentConnection');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentHoleOpener` (
  `id` BIGINT NOT NULL,
  `NumCutters` INT COMMENT 'Number of cutters on the tool.',
  `HoleOpenerDiameter` DOUBLE COMMENT 'Diameter of the reamer.',
  `HoleOpenerDiameterMaximum` DOUBLE COMMENT 'Maximum extended size of the hole opener when the arms are extended.',
  `FishneckLength` DOUBLE COMMENT 'Fishneck length of the hole opener. Dimension supplied by manufacturer. This dimension is used with the retrieval tool in case item is lost in hole.',
  `FlowRatePercent` DOUBLE COMMENT 'Flow rate percent across the tool',
  `TotalFlowArea` DOUBLE COMMENT 'Total Flow Area across the nozzles (jets)',
  `PluggedPercent` DOUBLE COMMENT '%% of the Hole Opener Nozzles plugged on retrieval of the tool',
  `HoleOpenerTypeID_id` INT COMMENT 'Type of hole opener - Under reamer or fixed blade.'
)
USING iceberg
COMMENT 'Hole Opener Component Schema. Describes the hole-opener tool (often called a ‘reamer’) used on the tubular string. Based on the WITSML Tubular \'HoleOpener\' ComplexType'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentHoleOpener');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentJar` (
  `id` BIGINT NOT NULL,
  `UpSetForce` DOUBLE COMMENT 'Specifies the force required to set the springs inside a mechanical jar into a position to trip the jar in an upward direction.',
  `DownSetForce` DOUBLE COMMENT 'Specifies the force required to set the springs inside a mechanical jar into a position to trip the jar in a downward direction.',
  `UpTripForce` DOUBLE COMMENT 'Specifies the force required to trip the jar upwards.',
  `DownTripForce` DOUBLE COMMENT 'Specifies the force required to trip the jar downward.',
  `PumpOpenForce` DOUBLE COMMENT 'Specifies the force present when jarring while circulating, and if pressure is trapped below the bit.',
  `SealFrictionForce` DOUBLE COMMENT 'Specifies the force required to move a hydraulic jar from the tripped position to the reset position so it can be tripped again. .',
  `JarTypeID_id` INT COMMENT 'Specifies the type of jar.',
  `JarActionTypeID_id` INT COMMENT 'Specifies the type of jar action.'
)
USING iceberg
COMMENT 'Captures information about drilling jars, which are mechanical or hydraulic devices used in the drill stem to deliver an impact load to another component of the drill stem, especially when that component is stuck.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentJar');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentMotor` (
  `id` BIGINT NOT NULL,
  `ToolOffset` DOUBLE COMMENT 'Tool offset distance from bottom of Tubular Assembly.',
  `PressureLossFactor` DOUBLE COMMENT 'Pressure drop across the tool.',
  `FlowRateMinimum` DOUBLE COMMENT 'Minimum flow rate for tool operation.',
  `FlowRateMaximum` DOUBLE COMMENT 'Maximum flow rate for tool operation.',
  `RotorNozzleDiameter` DOUBLE COMMENT 'Diameter of the rotor at the nozzle.',
  `BearingBoxClearance` DOUBLE COMMENT 'Clearance inside the bearing box.',
  `NumberRotorLobes` INT COMMENT 'Number of Rotor Lobes',
  `NumberStatorLobes` INT COMMENT 'Number of Stator Lobes',
  `OperatingTemperatureMaximum` DOUBLE COMMENT 'Maximum operating temperature for the mud motor',
  `IsRotorCatcherPresent` BOOLEAN COMMENT 'Is Rotor Catcher Present',
  `IsDumpValvePresent` BOOLEAN COMMENT 'Is Dump Valve Present',
  `NozzleDiameter` DOUBLE COMMENT 'Nozzle Diameter',
  `IsMotorRotatable` BOOLEAN COMMENT 'Is Motor Rotatable',
  `BendSettingAngleMinimum` DOUBLE COMMENT 'Minimum bend angle setting',
  `BendSettingAngleMaximum` DOUBLE COMMENT 'Maximum bend angle setting',
  `BearingTypeID_id` INT COMMENT 'Bearing Type Identifier'
)
USING iceberg
COMMENT 'Mud Motor Tubular Component specific properties. Based on WITSML Tubular  Component \'Motor\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentMotor');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentPressureLoss` (
  `id` BIGINT NOT NULL,
  `FlowRate` DOUBLE COMMENT 'Flow rate when pressure loss measured.',
