COMMENT 'Tubular Component Measured Pressure Losses - Flow rate versus Pressure'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentPressureLoss');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentRSS` (
  `id` BIGINT NOT NULL,
  `BendAngle` DOUBLE COMMENT 'Bend Angle.',
  `BendOffset` DOUBLE COMMENT 'Offset distance from the bottom connection to the bend,',
  `DownlinkFlowrateMinimum` DOUBLE COMMENT 'Minimum flow rate for programming the tool.',
  `DownlinkFlowrateMaximum` DOUBLE COMMENT 'Maximum flow rate for programming the tool.',
  `FlowRateMinimum` DOUBLE COMMENT 'Minimum flow rate for tool operation.',
  `FlowRateMaximum` DOUBLE COMMENT 'Maximum flow rate for tool operation.',
  `HoleSizeMininum` DOUBLE COMMENT 'Minimum size of the hole in which the tool can operate.',
  `HoleSizeMaximum` DOUBLE COMMENT 'Maximum size of the hole in which the tool can operate.',
  `OperatingSpeed` DOUBLE COMMENT 'Suggested operating speed.',
  `PressureLossFactor` DOUBLE COMMENT 'Pressure drop across the tool.',
  `SpeedMaximum` DOUBLE COMMENT 'Maximum rotation speed.',
  `WobMaximum` DOUBLE COMMENT 'Maximum weight on the bit.',
  `PadCount` INT COMMENT 'The number of contact pads.',
  `PadLength` DOUBLE COMMENT 'Length of the contact pad.',
  `PadWidth` DOUBLE COMMENT 'Width of the contact pad.',
  `PadOffset` DOUBLE COMMENT 'Offset distance from the bottom of the pad to the bottom connector.',
  `OpenPadOuterDiameter` DOUBLE COMMENT 'Outside diameter of the tool when the pads are activated.',
  `ClosePadOuterDiameter` DOUBLE COMMENT 'Outside diameter of the tool when the pads are closed.',
  `DeflectionMethodID_id` INT COMMENT 'Method used to direct the deviation of the trajectory: point bit or push bit'
)
USING iceberg
COMMENT 'Rotary Steerable Tool Tubular Component specific properties. Based on WITSML Tubular  Component \'RotarySteerableTool\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentRSS');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractTubularComponentStabiliser` (
  `id` BIGINT NOT NULL,
