  `BladeOuterDiameterMaximum` DOUBLE COMMENT 'Maximum Outer Diameter of the Blades.',
  `NumberBlades` INT COMMENT 'Number of blades on the Stabiliser.',
  `LengthBlade` DOUBLE COMMENT 'Length of the blade.',
  `LengthBladeGauge` DOUBLE COMMENT 'Gauge Length of the blade. That is, the length of the blade measured at the OD Blade Max.',
  `BladePadDiameter` DOUBLE COMMENT 'Width of the blade at the contact interval of the pad.',
  `FictionFactor` DOUBLE COMMENT 'Coefficient of Friction 0 - 1.',
  `StabiliserTypeID_id` INT COMMENT 'Stabiliser design classification.',
  `StabiliserBladeDesignTypeID_id` INT COMMENT 'Blade type classification.',
  `StabiliserOperatingDesignID_id` INT COMMENT 'Stabiliser operating design classification.'
)
USING iceberg
COMMENT 'Stabiliser Tubular Component specific properties. Based on the WITSML Tubular schema \'Stabiliser\' ComplexType.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractTubularComponentStabiliser');

CREATE TABLE IF NOT EXISTS demo.`abstract`.`AbstractWellboreDrillingReason` (
  `id` BIGINT NOT NULL,
  `EffectiveDateTime` TIMESTAMP COMMENT 'The date and time at which the event becomes effective.',
  `TerminationDateTime` TIMESTAMP COMMENT 'The date and time at which the event is no longer in effect.',
