)
USING iceberg
COMMENT 'Purpose for drilling a wellbore, which often is an indication of the level of risk.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'abstract/AbstractWellboreDrillingReason');

-- ========== schema: dataset (4 tables) ==========

CREATE TABLE IF NOT EXISTS demo.`dataset`.`FileCollection_Generic` (
  `id` BIGINT NOT NULL,
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `Name` STRING COMMENT 'An optional name of the dataset, e.g. a user friendly file or file collection name.',
  `Description` STRING COMMENT 'An optional, textual description of the dataset.',
  `TotalSize` STRING COMMENT 'Total size of the dataset in bytes; for files it is the same as declared in FileSourceInfo.FileSize or the sum of all individual files. Implemented as string. The value must be convertible to a long integer (sizes can become very large).',
  `Endian` STRING COMMENT 'Endianness of binary value.  Enumeration: "BIG", "LITTLE".  If absent, applications will need to interpret from context indicators.',
  `ResourceHomeRegionID_id` INT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` INT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` INT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` INT,
  `ExistenceKind_id` INT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` INT,
  `EncodingFormatTypeID_id` INT COMMENT 'EncodingFormatType ID reference value relationship. It can be a mime-type or media-type.',
  `SchemaFormatTypeID_id` INT COMMENT 'Relationship to the SchemaFormatType reference value.',
  `DatasetProperties_id` INT COMMENT 'The dataset properties for a file collection.'
)
USING iceberg
COMMENT 'The generic file collection template.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'dataset/FileCollection.Generic');

CREATE TABLE IF NOT EXISTS demo.`dataset`.`FileCollection_Generic_ResourceHostRegionIDs` (
  `dataset_FileCollection_Generic_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `ResourceHostRegionIDs_id` INT NOT NULL COMMENT 'The name of the host [cloud environment] region(s) for this OSDU resource object.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'dataset/FileCollection.Generic_ResourceHostRegionIDs');

CREATE TABLE IF NOT EXISTS demo.`dataset`.`File_Generic` (
  `id` BIGINT NOT NULL,
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `Name` STRING COMMENT 'An optional name of the dataset, e.g. a user friendly file or file collection name.',
  `Description` STRING COMMENT 'An optional, textual description of the dataset.',
  `TotalSize` STRING COMMENT 'Total size of the dataset in bytes; for files it is the same as declared in FileSourceInfo.FileSize or the sum of all individual files. Implemented as string. The value must be convertible to a long integer (sizes can become very large).',
  `Endian` STRING COMMENT 'Endianness of binary value.  Enumeration: "BIG", "LITTLE".  If absent, applications will need to interpret from context indicators.',
  `Checksum` STRING COMMENT 'MD5 checksum of file bytes - a 32 byte hexadecimal number.',
  `ResourceHomeRegionID_id` INT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` INT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` INT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` INT,
  `ExistenceKind_id` INT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
