CREATE TABLE IF NOT EXISTS demo.`master_data`.`TubularAssembly` (
  `id` BIGINT NOT NULL,
  `Name` STRING COMMENT 'The name of the Tubular Assembly.',
  `SuspensionPointMD` DOUBLE COMMENT 'The Measured Depth that the assembly is suspended from. This  \'point\' is typically the Measured Depth of the top of the assembly e.g. Hanger though with PBRs the Suspension Point may not be the top.',
  `TubularAssemblyNumber` INT COMMENT 'Sequence of the TubularAssembly (Typically BHA sequence or simply BHA #)',
  `ActivityTypeReasonDescription` STRING COMMENT 'Used to describe the reason of Activity - such as cut/pull, pulling,…',
  `IsMixedString` BOOLEAN COMMENT 'True if the assembly is a mixed string, else false. True where the Tubular Assembly is made up of joints with different Diameters, Weights, Grades, Connection, Tensile Strengths, Collapse Resistance or  Yield Strengths.',
  `IsInstalled` BOOLEAN COMMENT 'Indicates if the Tubular Assembly is currently downhole.',
  `TubularAssemblyNominalSize` DOUBLE COMMENT 'Nominal size (diameter) describing the whole assembly, e.g. 9.625", 12.25',
  `TubularAssemblyTotalLength` DOUBLE COMMENT 'Total Length of the whole assembly.',
  `DriftDiameter` DOUBLE COMMENT 'The drift diameter is the inside diameter (ID) that the pipe manufacturer guarantees per specifications. The drift diameter is used by the well planner to determine what size tools or casing strings can later be run through the casing, whereas the nominal inside diameter is used for fluid volume calculations such as mud circulating times and cement slurry placement calculations. Note that the nominal inside diameter is not the same as the drift diameter but is always slightly larger.',
  `MinimumInnerDiameter` DOUBLE COMMENT 'This is the minimum inner diameter of the whole Tubular Assembly.',
  `PilotHoleSize` DOUBLE COMMENT 'Diameter of the Pilot Hole (drillstrings)',
  `SeaFloorPenetrationLength` DOUBLE COMMENT 'The distance that the Tubular Assembly has penetrated below the surface of the sea floor.',
  `AssemblyTopMD` DOUBLE COMMENT 'The measured depth at the top of the Tubular Assembly',
  `AssemblyBaseMD` DOUBLE COMMENT 'The measured depth at the base (bottom) of the Tubular Assembly',
  `AssemblyTopReportedTVD` DOUBLE COMMENT 'True Vertical Depth of the top of the Assembly',
  `AssemblyBaseReportedTVD` DOUBLE COMMENT 'True Vertical Depth of the base of the Assembly',
  `CirculatedHours` DOUBLE COMMENT 'Hours Circulated before running Assembly',
  `FluidBehindDensity` DOUBLE COMMENT 'Density of Fluid Behind Assembly',
  `FluidLostVolume` DOUBLE COMMENT 'Fluid Lost Volume when running assembly in hole',
  `InSlipsWeight` DOUBLE COMMENT 'Weight of Assembly in Slips',
  `IsFluidLost` BOOLEAN COMMENT 'Is Fluid Lost',
  `IsParallel` BOOLEAN COMMENT 'Is Parallel/Dual Assembly',
  `HoleAngleMax` DOUBLE COMMENT 'Maximum Hole Angle',
  `InHoleDate` TIMESTAMP COMMENT 'Date/time Assembly started to be run in hole',
  `LandedDate` TIMESTAMP COMMENT 'Date/time assembly was set/landed',
  `LandedDepthAdjustment` DOUBLE COMMENT 'Depth Adjustment for use in Landed Depth calculation. Set MD = Top MD + Assembly Length + Depth Adjustment. Note that Depth Adjustment can be positive or negative length.',
  `LandedWeight` DOUBLE COMMENT 'Weight of Assembly when Landed',
  `TaggedMD` DOUBLE COMMENT 'Tagged Measured Depth comparison to estimated Landed Depth',
  `OpenHoleDiameter` DOUBLE COMMENT 'Open Hole Size/Diameter behind Assembly',
  `EstimatedWeightBelowJar` DOUBLE COMMENT 'Estimated Weight Below Jar',
  `MaximumOuterDiameter` DOUBLE COMMENT 'Maximum Outer Diameter',
  `MaximumOuterDiameterMD` DOUBLE COMMENT 'Maximum Outer Diameter Measured Depth',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `VersionCreationReason` STRING COMMENT 'This describes the reason that caused the creation of a new version of this master data.',
  `ParentWellboreID_id` BIGINT COMMENT 'Identifier of the Wellbore the Assembly is installed into or run in. Note: it may not be same wellbore that current assembly is installed into.',
  `ParentAssemblyID_id` BIGINT COMMENT 'Optional - Identifier of the parent assembly (in case of side-track, multi-nesting,…) - The Concentric Tubular model is used to identify the Assembly that an Assembly sits inside e.g. Surface Casing set inside Conductor, Tubing set inside Production Casing, a Bumper Spring set inside a Production Tubing Profile Nipple, Liner set inside Casing, etc. This is needed to enable a Digital Well Sketch application to understand relationships between Assemblies including those in parent Wellbores.',
  `VerticalMeasurement_id` BIGINT COMMENT 'Either a self-contained vertical reference for the depths in this TubularAssembly or a reference (VerticalReferenceID) to an element in data.VerticalMeasurements[] in the entity defined by VerticalReferenceEntityID e.g. the parent Well.',
  `TubularAssemblyTypeID_id` BIGINT COMMENT 'Type of tubular assembly.',
  `StringClassID_id` BIGINT COMMENT 'Descriptor for Assembly, e.g. Production, Surface, Conductor, Intermediate, Drilling',
  `ActivityTypeID_id` BIGINT COMMENT 'Used to describe if it belongs to a RunActivity or to a PullActivity',
  `ArtificialLiftTypeID_id` BIGINT COMMENT 'Type of Artificial Lift supported by the TubularAssembly where applicable E.g. could be "Surface Pump" / "Submersible Pump" / "Gas Lift", etc',
  `LinerTypeID_id` BIGINT COMMENT 'This reference table describes the type of liner used in the borehole where applicable. For example, slotted, gravel packed or pre-perforated etc.',
  `TubularDirectionID_id` BIGINT COMMENT 'Defines whether the sequence of child tubular components runs either top to bottom, or bottom to top.',
  `ContractorID_id` BIGINT COMMENT 'Tubular Running Contractor',
  `FluidBehindTypeID_id` BIGINT COMMENT 'Type of fluid behind (outside) assembly',
  `TubularAssemblyStatus_id` BIGINT COMMENT 'Reflects the current status of the Assembly - as \'installed\', \'pulled\', \'planned\',... - Applicable to tubing/completions as opposed to drillstrings. Historical states are recorded in TubularAssemblyStates.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialLocation_id` BIGINT COMMENT 'The spatial location information such as coordinates, CRS information (left empty when not appropriate).',
  `TechnicalAssuranceTypeID_id` BIGINT
)
USING iceberg
COMMENT 'Well Tubular data contains information on the tubular assemblies and their components for the well, wellbore, or wellbore completion (as appropriate). Tubulars can be tubing, casing or liners or other related equipment which is installed into the well. Tubulars can also be equipment which is lowered into the well in the context of drilling, which is then pulled back out e.g. a drillstring or workstring.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/TubularAssembly');

