  `master_data_TubularAssembly_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `ResourceHostRegionIDs_id` INT NOT NULL COMMENT 'The name of the host [cloud environment] region(s) for this OSDU resource object.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/TubularAssembly_ResourceHostRegionIDs');

CREATE TABLE IF NOT EXISTS demo.`master_data`.`TubularComponent` (
  `id` BIGINT NOT NULL,
  `Name` STRING COMMENT 'The name of this tubular component.',
  `TubularComponentSequence` INT COMMENT 'The sequence within which the components entered the hole. That is, a sequence number of 1 entered first, 2 entered 2nd, etc.',
  `TubularComponentNominalSize` DOUBLE COMMENT 'Nominal size (outer diameter \'OD\') of the component, e.g. 9.625", 12.25"',
