  `TubularComponentNominalWeight` DOUBLE COMMENT 'Nominal weight of the component.',
  `TubularComponentLength` DOUBLE COMMENT 'Total Length of the component(s)',
  `MaximumOuterDiameter` DOUBLE COMMENT 'This is the maximum hard outer diameter of the component.',
  `DriftDiameter` DOUBLE COMMENT 'The drift diameter is the inside diameter (ID) that the pipe manufacturer guarantees per specifications. Note that the nominal inside diameter is not the same as the drift diameter but is always slightly larger. The drift diameter is used by the well planner to determine what size tools or casing strings can later be run through the casing, whereas the nominal inside diameter is used for fluid volume calculations such as mud circulating times and cement slurry placement calculations.',
  `InnerDiameter` DOUBLE COMMENT 'Nominal inner diameter \'ID\' of the component.',
  `Model` STRING COMMENT 'Name of the component Model as defined per the operating company',
  `SerialNumber` STRING COMMENT 'Serial Number of the component as provided by the manufacturer and/or the supplier',
  `TubularComponentTubingGradeStrength` DOUBLE COMMENT 'The tensile strength of the tubing material. A system of classifying the material specifications for steel alloys used in the manufacture of tubing.',
  `TubularComponentTubingStrength` DOUBLE COMMENT 'The axial load required to yield the pipe.',
  `PilotHoleSize` DOUBLE COMMENT 'Size/diameter of the Pilot Hole when assembly is a drillstring',
  `TubularComponentTopMD` DOUBLE COMMENT 'The installed measured depth of the top of the specific component',
  `TubularComponentBaseMD` DOUBLE COMMENT 'The installed measured depth of the base of the specific component',
  `TubularComponentTopReportedTVD` DOUBLE COMMENT 'True Vertical Depth of the top of the component measured from the Wellhead',
  `TubularComponentBaseReportedTVD` DOUBLE COMMENT 'True Vertical Depth of the base of the component measured from the Wellhead',
  `PackerSetDepthTVD` DOUBLE COMMENT 'The depth the packer equipment was set to seal the casing or tubing.',
  `ShoeDepthTVD` DOUBLE COMMENT 'True vertical depth of the casing/tubing shoe measured from the surface.',
  `NumJoints` INT COMMENT 'Number of Joints per pipe section',
  `JointLengthAverage` DOUBLE COMMENT 'Average Joint Length',
  `TopConnOD` DOUBLE COMMENT 'Top Connection Outer Diameter',
  `TopConnLength` DOUBLE COMMENT 'Top Connection Outer Length',
  `BotConnOD` DOUBLE COMMENT 'Bottom Connection Outer Diameter',
  `BotConnLength` DOUBLE COMMENT 'Bottom Connection Outer Length',
  `OutsideCouplingLength` DOUBLE COMMENT 'Outside Coupling Length',
  `IsThreadLockUsed` BOOLEAN COMMENT 'Is thread lock used when making up the pipe?',
  `LinearCapacity` DOUBLE COMMENT 'Linear Capacity volume/length inside component',
  `ClosedEndDisplacement` DOUBLE COMMENT 'Closed End Displacement volume/length',
  `MakeUpTorqueMin` DOUBLE COMMENT 'Minimum Make Up Torque',
  `MakeUpTorqueOpt` DOUBLE COMMENT 'Optimum Make Up Torque',
  `MakeUpTorqueMax` DOUBLE COMMENT 'Maximum Make Up Torque',
  `MakeUpTorqueAct` DOUBLE COMMENT 'Actual Make Up Torque',
  `YoungsModulus` DOUBLE COMMENT 'Youngs Modulus of Elasticity',
  `PoissonsRatio` DOUBLE COMMENT 'Poissons Ratio',
  `Density` DOUBLE COMMENT 'Density',
  `BurstPressure` DOUBLE COMMENT 'Burst Pressure',
  `CollapsePressure` DOUBLE COMMENT 'Collapse Pressure',
  `InternalReference` STRING COMMENT 'Internal Reference name/description',
  `AxialLoadCapacity` DOUBLE COMMENT 'Axial Load Capacity of component',
  `IsRadioActive` BOOLEAN COMMENT 'Is Radioactive',
  `PartNumber` STRING COMMENT 'Vendor part number',
  `VendorNumber` STRING COMMENT 'Vendor number or other reference identifier',
  `TotalFlowArea` DOUBLE COMMENT 'TFA of all Nozzles',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `VersionCreationReason` STRING COMMENT 'This describes the reason that caused the creation of a new version of this master data.',
  `ParentWellboreID_id` BIGINT COMMENT 'Identifier of the wellbore the Component is installed/run into.',
  `ParentAssemblyID_id` BIGINT COMMENT 'Identifier of the Assembly the component is part of.',
  `ManufacturerID_id` BIGINT COMMENT 'Unique identifier for the manufacturer of this equipment.',
  `SupplierID_id` BIGINT COMMENT 'Unique identifier for the supplier of this equipment.',
  `SectionTypeID_id` BIGINT COMMENT 'Identifier of the Section Type.',
  `TubularComponentTypeID_id` BIGINT COMMENT 'Specifies the types of components that can be used in a tubular string. These are used to specify the type of component and multiple components are used to define a tubular string (Tubular).',
  `TubularComponentMaterialTypeID_id` BIGINT COMMENT 'Specifies the material type constituting the component.',
  `TubularComponentTubingGradeID_id` BIGINT COMMENT 'Id of tubing grade - eg. the tensile strength of the tubing material. A system of classifying the material specifications for steel alloys used in the manufacture of tubing.',
  `TubularComponentBoxPinConfigID_id` BIGINT COMMENT 'Box / Pin configuration Identifier',
