  `TubularComponentBottomConnectionTypeID_id` BIGINT COMMENT 'Identifier of the Bottom Connection Type',
  `Bend_id` BIGINT COMMENT 'Bend specific information',
  `BitRecord_id` BIGINT COMMENT 'Bit Record specific information',
  `HoleOpener_id` BIGINT COMMENT 'Hole Opener specific information',
  `Jar_id` BIGINT COMMENT 'Drilling Jar specific information',
  `Motor_id` BIGINT COMMENT 'Mud Motor specific information',
  `MWDTool_id` BIGINT COMMENT 'MWD Tool specific information',
  `PressureLoss_id` BIGINT COMMENT 'Pressure v flow rate curve data for Hydraulics Pressure Loss calculations',
  `RotarySteerableSystem_id` BIGINT COMMENT 'Rotary Steerable System (RSS) tool specific information',
  `Stabiliser_id` BIGINT COMMENT 'Stabiliser specific information',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialLocation_id` BIGINT COMMENT 'The spatial location information such as coordinates, CRS information (left empty when not appropriate).',
  `TechnicalAssuranceTypeID_id` BIGINT
)
USING iceberg
COMMENT 'Well Tubular data contains information on the tubular assemblies installed into the well, wellbore, or wellbore completion (as appropriate). Tubulars can be tubing, casing or liners or other related equipment which is installed into the well. Tubulars can also be equipment which is lowered into the well e.g. a drillstring, which is then pulled back out.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/TubularComponent');

