CREATE TABLE IF NOT EXISTS demo.`master_data`.`Well` (
  `id` BIGINT NOT NULL,
  `DefaultVerticalMeasurementID` STRING COMMENT 'The default datum reference point, or zero depth point, used to determine other points vertically in a well.  References an entry in the VerticalMeasurements array.',
  `WasBusinessInterestFinancialOperated` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this well has ever been FinancialOperated in the past.',
  `WasBusinessInterestFinancialNonOperated` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this well has ever been FinancialNonOperated in the past.',
  `WasBusinessInterestObligatory` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this well has ever been Obligatory in the past.',
  `WasBusinessInterestTechnical` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this well has ever been Technical in the past.',
  `SlotID` STRING COMMENT 'Optional identifier of a slot. It requires that the relationship WellSiteStructureID is populated. SlotID must match a member in the related WellSiteStructure data.WellSlots[].SlotID.',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `VersionCreationReason` STRING COMMENT 'This describes the reason that caused the creation of a new version of this master data.',
  `FacilityID` STRING COMMENT 'Native identifier from a Master Data Management System or other trusted source external to OSDU - stored here in order to allow for multi-system connection and synchronization. If used, the "Source" property should identify that source system.',
  `FacilityName` STRING COMMENT 'Name of the Facility.',
  `FacilityDescription` STRING COMMENT 'A descriptive text or remark about the Facility.',
  `DefaultVerticalCRSID_id` INT COMMENT 'The default vertical coordinate reference system used in the vertical measurements for a well or wellbore if absent from input vertical measurements and there is no other recourse for obtaining a valid CRS.',
  `InterestTypeID_id` INT COMMENT 'Business Interest [Well Interest Type] describes whether a company currently considers a well or its data to be a real or planned asset, and if so, the nature of and motivation for that company\'s interest.',
  `BusinessIntentionID_id` INT COMMENT 'Business Intention [Well Business Intention] is the general purpose for which resources are approved for drilling a new well or subsequent wellbore(s).',
  `RoleID_id` INT COMMENT 'Role [Well Role] is the current purpose, whether planned or actual. If there are multiple Roles among a well\'s components, the well may be assigned the facet value with the highest significance. The value of Role may change over the Life Cycle.',
  `ConditionID_id` INT COMMENT 'Condition [Well Condition] is the operational state of a well component relative to the Role [Well Role].',
  `OutcomeID_id` INT COMMENT 'Outcome [Well Drilling Outcome] is the result of attempting to accomplish the Business Intention [Well Business Intention].',
  `StatusSummaryID_id` INT COMMENT 'Identifies the status of a well component in a way that may combine and-or summarize concepts found in other status facets. For example, a Well Status Summary of Gas Injector Shut-in, which contains commonly desired business information, combines concepts from Product Type, Fluid Direction, and Condition.',
  `LocationUncertainty_id` INT COMMENT 'Uncertainty for well location',
  `WellSiteStructureID_id` INT COMMENT 'An optional relationship to a WellSiteStructure, e.g., Pad, Platform, Subsea Template.',
  `ResourceHomeRegionID_id` INT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` INT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` INT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` INT,
  `ExistenceKind_id` INT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` INT,
  `SpatialLocation_id` INT COMMENT 'The spatial location information such as coordinates, CRS information (left empty when not appropriate).',
  `TechnicalAssuranceTypeID_id` INT,
  `FacilityTypeID_id` INT COMMENT 'The definition of a kind of capability to perform a business function or a service.',
  `InitialOperatorID_id` INT COMMENT 'A initial operator organization ID; the organization ID may also be found in the FacilityOperatorOrganisationID of the FacilityOperator array providing the actual dates.',
  `CurrentOperatorID_id` INT COMMENT 'The current operator organization ID; the organization ID may also be found in the FacilityOperatorOrganisationID of the FacilityOperator array providing the actual dates.',
  `DataSourceOrganisationID_id` INT COMMENT 'The main source of the header information.',
  `OperatingEnvironmentID_id` INT COMMENT 'Identifies the Facility\'s general location as being onshore vs. offshore.'
)
USING iceberg
COMMENT 'The origin of a set of wellbores.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/Well');

