  `master_data_Well_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `ResourceHostRegionIDs_id` INT NOT NULL COMMENT 'The name of the host [cloud environment] region(s) for this OSDU resource object.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/Well_ResourceHostRegionIDs');

CREATE TABLE IF NOT EXISTS demo.`master_data`.`Wellbore` (
  `id` BIGINT NOT NULL,
  `SequenceNumber` INT COMMENT 'A number that indicates the order in which wellbores were drilled.',
  `FormationNameAtTotalDepth` STRING COMMENT 'The name of the formation encountered at total depth. The value is not controlled by any reference value list.',
  `DefaultVerticalMeasurementID` STRING COMMENT 'The default datum reference point, or zero depth point, used to determine other points vertically in a wellbore.  References an entry in the Vertical Measurements array of this wellbore.',
  `WasBusinessInterestFinancialOperated` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this Well has ever been FinancialOperated in the past.',
  `WasBusinessInterestFinancialNonOperated` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this Well has ever been FinancialNonOperated in the past.',
  `WasBusinessInterestObligatory` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this Well has ever been Obligatory in the past.',
  `WasBusinessInterestTechnical` BOOLEAN COMMENT 'Identifies, for the purpose of current use, if the Business Interest [Well Interest Type] for this Well has ever been Technical in the past.',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `VersionCreationReason` STRING COMMENT 'This describes the reason that caused the creation of a new version of this master data.',
  `FacilityID` STRING COMMENT 'Native identifier from a Master Data Management System or other trusted source external to OSDU - stored here in order to allow for multi-system connection and synchronization. If used, the "Source" property should identify that source system.',
  `FacilityName` STRING COMMENT 'Name of the Facility.',
  `FacilityDescription` STRING COMMENT 'A descriptive text or remark about the Facility.',
  `WellID_id` BIGINT,
  `WellboreReasonID_id` BIGINT COMMENT 'The relationship to a reference-data record explaining the reason why this wellbore was drilled.',
  `KickOffWellbore_id` BIGINT COMMENT 'This is a pointer to the parent wellbore. The wellbore that starts from top has no parent.',
  `TrajectoryTypeID_id` BIGINT COMMENT 'Profile Type [Wellbore Trajectory Type] is the general geometry of the wellbore relative to the vertical plane. The specific criteria for Profile Type may vary by operator or regulator. The facet value may change if conditions encountered during drilling are not what was planned or permitted.',
  `DefinitiveTrajectoryID_id` BIGINT COMMENT 'SRN of Wellbore Trajectory which is considered the authoritative or preferred version.',
  `TargetFormation_id` BIGINT COMMENT 'The Formation of interest for which the Wellbore is drilled to interact with. The Wellbore may terminate in a lower formation if the requirement is to drill through the entirety of the target formation, therefore this is not necessarily the Formation at TD.',
  `PrimaryMaterialID_id` BIGINT,
  `ProjectedBottomHoleLocation_id` BIGINT COMMENT 'The bottom hole location of the wellbore denoted by a projected horizontal coordinate reference system (Horizontal CRS), such a UTM zone. \'Projected\' in this property does not mean \'planned\' or \'projected-to-bit\'. If both GeographicBottomHoleLocation and ProjectedBottomHoleLocation properties are populated on this wellbore, they must identify the same point, just in different CRSs.',
  `GeographicBottomHoleLocation_id` BIGINT COMMENT 'The bottom hole location of the wellbore denoted by a specified geographic horizontal coordinate reference system (Horizontal CRS), such as WGS84, NAD27, or ED50. If both GeographicBottomHoleLocation and ProjectedBottomHoleLocation properties are populated on this wellbore, they must identify the same point, just in different CRSs.',
  `BusinessIntentionID_id` BIGINT COMMENT 'Business Intention [Well Business Intention] is the general purpose for which resources are approved for drilling a new well or subsequent wellbore(s).',
  `RoleID_id` BIGINT COMMENT 'Role [Well Role] is the current purpose, whether planned or actual. If there are multiple Roles among a wellbore\'s components, the well may be assigned the facet value with the highest significance. The value of Role may change over the Life Cycle.',
  `InterestTypeID_id` BIGINT COMMENT 'Business Interest [Well Interest Type] describes whether a company currently considers a wellbore entity or its data to be a real or planned asset, and if so, the nature of and motivation for that company\'s interest.',
  `WellboreTrajectoryTypeID_id` BIGINT,
  `PrimaryProductTypeID_id` BIGINT COMMENT 'Product Type [Well Product Type] is the physical product(s) that can be attributed to any wellbore component. A Primary Product Significance identifies the Product Type that is most significant.',
  `SecondaryProductTypeID_id` BIGINT COMMENT 'Product Type [Well Product Type] is the physical product(s) that can be attributed to any wellbore component. A Secondary Product Significance identifies the Product Type that is the second most significant.',
  `TertiaryProductTypeID_id` BIGINT COMMENT 'Product Type [Well Product Type] is the physical product(s) that can be attributed to any wellbore component. A Tertiary Product Significance identifies the Product Type that is the third most significant.',
  `ShowProductTypeID_id` BIGINT COMMENT 'Product Type [Well Product Type] is the physical product(s) that can be attributed to any wellbore component. A Show Product Significance identifies a Product Type present in non-commercial quantity.',
  `ConditionID_id` BIGINT COMMENT 'Condition [Well Condition] is the operational state of a wellbore component relative to the Role [Well Role].',
  `FluidDirectionID_id` BIGINT COMMENT 'Fluid Direction [Well Fluid Direction] is the flow direction of the wellhead stream. The facet value can change over the life of the wellbore.',
  `OutcomeID_id` BIGINT COMMENT 'Outcome [Well Drilling Outcome] is the result of attempting to accomplish the Business Intention [Well Business Intention].',
  `StatusSummaryID_id` BIGINT COMMENT 'Identifies the status of a wellbore component in a way that may combine and-or summarize concepts found in other status facets. For example, a Wellbore Status Summary of Gas Injector Shut-in, which contains commonly desired business information, combines concepts from Product Type, Fluid Direction, and Condition.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialLocation_id` BIGINT COMMENT 'The spatial location information such as coordinates, CRS information (left empty when not appropriate).',
  `TechnicalAssuranceTypeID_id` BIGINT,
  `FacilityTypeID_id` BIGINT COMMENT 'The definition of a kind of capability to perform a business function or a service.',
  `InitialOperatorID_id` BIGINT COMMENT 'A initial operator organization ID; the organization ID may also be found in the FacilityOperatorOrganisationID of the FacilityOperator array providing the actual dates.',
  `CurrentOperatorID_id` BIGINT COMMENT 'The current operator organization ID; the organization ID may also be found in the FacilityOperatorOrganisationID of the FacilityOperator array providing the actual dates.',
  `DataSourceOrganisationID_id` BIGINT COMMENT 'The main source of the header information.',
  `OperatingEnvironmentID_id` BIGINT COMMENT 'Identifies the Facility\'s general location as being onshore vs. offshore.'
)
USING iceberg
COMMENT 'A hole in the ground extending from a point at the earth\'s surface to the maximum point of penetration.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'master-data/Wellbore');

