CREATE TABLE IF NOT EXISTS demo.`osdu`.`AbstractWPCGroupTypeArtefacts` (
  `id` BIGINT NOT NULL,
  `ResourceKind` STRING COMMENT 'The kind or schema ID of the artefact. Resolvable with the Schema Service.',
  `ResourceID` STRING COMMENT 'The SRN which identifies this OSDU Artefact resource.',
  `work_product_component_Document_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_PPFGDataset_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellLog_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreIntervalSet_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreMarkerSet_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreTrajectory_id` INT COMMENT 'Autocreated FK slot',
  `RoleID_id` INT COMMENT 'The record id of this artefact\'s role.'
)
USING iceberg
COMMENT 'An array of Artefacts - each artefact has a Role, Resource tuple. An artefact is distinct from the file, in the sense certain valuable information is generated during loading process (Artefact generation process). Examples include retrieving location data, performing an OCR which may result in the generation of artefacts which need to be preserved distinctly'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'AbstractWPCGroupTypeArtefacts');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`AbstractWorkProductComponentLineageAssertions` (
  `id` BIGINT NOT NULL,
  `work_product_component_Document_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_PPFGDataset_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellLog_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreIntervalSet_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreMarkerSet_id` INT COMMENT 'Autocreated FK slot',
  `work_product_component_WellboreTrajectory_id` INT COMMENT 'Autocreated FK slot',
  `LineageRelationshipType_id` INT COMMENT 'Used by LineageAssertion to describe the nature of the line of descent of a work product component from a prior Resource, such as DIRECT, INDIRECT, REFERENCE.  It is not for proximity (number of nodes away), it is not to cover all the relationships in a full ontology or graph, and it is not to describe the type of activity that created the asserting WPC.  LineageAssertion does not encompass a full provenance, process history, or activity model.'
)
USING iceberg
COMMENT 'Defines relationships with other objects (any kind of Resource) upon which this work product component depends.  The assertion is directed only from the asserting WPC to ancestor objects, not children.  It should not be used to refer to files or artefacts within the WPC -- the association within the WPC is sufficient and Artefacts are actually children of the main WPC file. They should be recorded in the data.Artefacts[] array.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'AbstractWorkProductComponentLineageAssertions');

