CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellLogCurves` (
  `id` BIGINT NOT NULL,
  `CurveID` STRING COMMENT 'The ID of the Well Log Curve',
  `DateStamp` TIMESTAMP COMMENT 'Date curve was created in the database',
  `CurveVersion` STRING,
  `CurveQuality` STRING COMMENT 'The Quality of the Log Curve.',
  `InterpreterName` STRING COMMENT 'The name of person who generated, improved or QC\'d this Log Curve.  This excludes the name of the person who loaded or ingested the data.',
  `IsRegularlySampled` BOOLEAN COMMENT 'Indicates if the curve is regularly or irregularly sampled. Not to be confused with the `data.IsRegular` attribute at Log Level which indicates regularity of the reference curve only.',
  `IsProcessed` BOOLEAN,
  `NullValue` BOOLEAN COMMENT 'Indicates that there is no measurement within the curve. This attribute is required for the Wellbore DDMS.',
  `DepthCoding` STRING,
  `Interpolate` BOOLEAN,
  `TopDepth` DOUBLE,
  `BaseDepth` DOUBLE,
  `SamplingStart` DOUBLE COMMENT 'The start or smallest value of the ReferenceCurveID, typically the start depth or time of the logging.',
  `SamplingStop` DOUBLE COMMENT 'The stop or largest value of the ReferenceCurveID, typically the stop depth or time of the logging.',
  `Mnemonic` STRING COMMENT 'A short or abbreviated form of the curve name, typically provided by the logging vendor or the processing company.  Curve mnemonics have meaning to expert users.',
  `NumberOfColumns` INT COMMENT 'The number of columns present in this Curve for a single reference value.  Most curves only have one column per curve.  A single curve may contain an array of columns, and these are commonly present in curves that display as images, for example Borehole Image logs or Variable Density Logs.',
  `CurveDescription` STRING COMMENT 'Curve description is specific to that single curve mnemonic. In essence, curve description defines the internal factors such as what the "curve" or measurement ideally is representing, how is it calculated, what are the assumptions and the "constants".',
  `work_product_component_WellLog_id` INT COMMENT 'Autocreated FK slot',
  `DepthUnit_id` INT COMMENT 'Unit of Measure for TopDepth and BaseDepth.',
  `CurveUnit_id` INT COMMENT 'Unit of Measure for the Log Curve',
  `LogCurveTypeID_id` INT,
  `LogCurveBusinessValueID_id` INT COMMENT 'The related record id of the Log Curve Business Value Type.',
  `LogCurveMainFamilyID_id` INT COMMENT 'The related record id of the Log Curve Main Family Type - which is the Geological Physical Quantity measured - such as porosity.',
  `LogCurveFamilyID_id` INT COMMENT 'The related record id of the Log Curve Family - which is the detailed Geological Physical Quantity Measured - such as neutron porosity',
  `CurveSampleTypeID_id` INT COMMENT 'The value type to be expected as curve sample values.'
)
USING iceberg
COMMENT 'A curve is a data type that is represented by a series of digits, and are commonly displayed as a continuous line or a series of points referenced to the WellLog reference curve.   A WellLog commonly contains multiple curves.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellLogCurves');

