CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreIntervalSetIntervals` (
  `id` BIGINT NOT NULL,
  `IntervalID` STRING COMMENT 'The unique identifier of the interval array member in the data.Intervals[] array. Ideally a UUID. IntervalID is also used to associate IntervalProperties via the key column data.IntervalProperties.ColumnValues[0].StringColumn[].',
  `StartMeasuredDepth` DOUBLE COMMENT 'The minimal MeasuredDepth of the interval. In the most common case this is the top.  If this value is associated with a marker then this value is a denormalization of data.Markers[].MarkerMeasuredDepth where the data.Markers[].MarkerID equals to StartMarkerID.',
  `StartSubSeaVerticalDepth` DOUBLE COMMENT 'True vertical depth sub-sea of the start of the interval. This is the same as true vertical depth referenced to the vertical CRS "MSL depth". If the start of the interval is associated with a marker then this value is a denormalization of data.Markers[].MarkerSubSeaVerticalDepth where the data.Markers[].MarkerID equals to StartMarkerID.',
  `StartIntervalName` STRING COMMENT 'Name of the interval start (typically the top); when associated with a marker in a WellboreMarkerSet then this name is a denormalization of data.Markers[].MarkerName where the data.Markers[].MarkerID equals to StartMarkerID.',
  `StartMarkerID` STRING COMMENT 'Individual markers are not globally identifiable. TopMarkerID is the unique id (MarkerID) of the top interval marker (typically the interval base) in the data.Markers[] array where the data.Markers[].MarkerID equals to StartMarkerID.',
  `StopMeasuredDepth` DOUBLE COMMENT 'The maximum MeasuredDepth of the interval (typically the base). If the interval stop is associated with a marker then this value is a denormalization of data.Markers[].MarkerMeasuredDepth where the data.Markers[].MarkerID equals to StopMarkerID.',
  `StopSubSeaVerticalDepth` DOUBLE COMMENT 'True vertical depth sub-sea of the interval stop (typically the base). This is the same as true vertical depth referenced to the vertical CRS "MSL depth". If the interval stop is associated with a marker then this value is a denormalization of data.Markers[].MarkerSubSeaVerticalDepth where the data.Markers[].MarkerID equals to StopMarkerID.',
  `StopIntervalName` STRING COMMENT 'Name of the interval stop (typically the base); when associated with a marker in a WellboreMarkerSet then this name is a denormalization of data.Markers[].MarkerName where the data.Markers[].MarkerID equals to StopMarkerID.',
  `StopMarkerID` STRING COMMENT 'Individual markers are not globally identifiable. StopMarkerID is the unique id (MarkerID) of the interval stop (typically the interval base) in the data.Markers[] array where the data.Markers[].MarkerID equals to StopMarkerID.',
  `work_product_component_WellboreIntervalSet_id` INT COMMENT 'Autocreated FK slot',
  `StartMarkerSetID_id` INT COMMENT 'Optional reference to the WellboreMarkerSet containing the interval start (typically the top), with MarkerID equals StartMarkerID.',
  `StartBoundaryInterpretationID_id` INT COMMENT 'The optional relationship to a HorizonInterpretation, GeobodyBoundaryInterpretation or FaultInterpretation. If the interval start (typically the top) is associated with a marker, this is considered a denormalization of the data.Markers[].InterpretationID for the data.Markers[].MarkerID equals to StartMarkerID.',
  `StopMarkerSetID_id` INT COMMENT 'Optional reference to the WellboreMarkerSet containing the top with MarkerID equals StopMarkerID.',
  `StopBoundaryInterpretationID_id` INT COMMENT 'The optional relationship to a HorizonInterpretation, GeobodyBoundaryInterpretation or FaultInterpretation. If the interval stop (typically the base) is associated with a marker, this is considered a denormalization of the data.Markers[].InterpretationID where the data.Markers[].MarkerID equals to StopMarkerID.'
)
USING iceberg
COMMENT 'An interval given either by relationships to top/base markers or standalone top/base depths. To avoid confusion about entry and exit depths the naming convention uses Start as the entry point of the well path into the geologic unit and Stop as the exit point. For unfolded geologic units and vertical wellbores Start is Top and Stop is Base.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreIntervalSetIntervals');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreIntervalSetIntervals_GeologicUnitInterpretationIDs` (
  `WellboreIntervalSetIntervals_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `GeologicUnitInterpretationIDs` STRING NOT NULL COMMENT 'An array of StratigraphicUnitInterpretation, GeobodyInterpretation or RockFluidUnitInterpretation record Ids associated to this interval.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreIntervalSetIntervals_GeologicUnitInterpretationIDs');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreMarkerSetAvailableMarkerProperties` (
  `id` BIGINT NOT NULL,
  `Name` STRING COMMENT 'The name of the marker property (e.g. column in a CSV document) as originally found. If absent The name of the MarkerPropertyType is intended to be used.',
  `work_product_component_WellboreMarkerSet_id` INT COMMENT 'Autocreated FK slot',
  `MarkerPropertyTypeID_id` INT COMMENT 'The reference to a marker property type - or if interpreted as CSV columns, the \'well-known column type. It is a relationship to a reference-data--MarkerPropertyType record id.',
  `MarkerPropertyUnitID_id` INT COMMENT 'Unit of Measure for the marker properties of type MarkerPropertyType.'
)
USING iceberg
COMMENT 'A set of properties describing a marker property which is available for this instance of a WellboreMarkerSet.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreMarkerSetAvailableMarkerProperties');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreMarkerSetMarkers` (
  `id` BIGINT NOT NULL,
  `MarkerName` STRING COMMENT 'Name of the Marker',
  `MarkerID` STRING COMMENT 'A unique identifier of the marker in the list of data.Markers[], ideally a UUID. If unpopulated, the string-converted element index number is used. The first index is "0". MarkerID is also used to associate MarkerProperties via the key column data.MarkerProperties.ColumnValues[0].StringColumn[].',
  `MarkerMeasuredDepth` DOUBLE COMMENT 'The depth at which the Marker was noted.',
  `MarkerSubSeaVerticalDepth` DOUBLE COMMENT 'The Marker\'s TVD converted to a Sub-Sea Vertical depth, i.e., below Mean Sea Level. Note that TVD values above MSL are negative. This is the same as true vertical depth referenced to the vertical CRS “MSL depth”.',
  `MarkerDate` TIMESTAMP COMMENT 'Timestamp of the date and time when the when the Marker was interpreted.',
  `MarkerObservationNumber` DOUBLE COMMENT 'Any observation number that distinguishes a Marker observation from others with same Marker name, date.',
  `MarkerInterpreter` STRING COMMENT 'The name of the Marker interpreter (could be a person or vendor).',
  `FeatureName` STRING COMMENT 'Name of the feature the marker is characterizing',
  `PositiveVerticalDelta` DOUBLE COMMENT 'The distance vertically above the Marker position that marks the limit of the high confidence range for the Marker pick.',
  `NegativeVerticalDelta` DOUBLE COMMENT 'The distance vertically below the Marker position that marks the limit of the high confidence range for the Marker pick.',
  `SurfaceDipAngle` DOUBLE COMMENT 'Dip angle for the Wellbore Marker.',
  `SurfaceDipAzimuth` DOUBLE COMMENT 'Dip azimuth for the Wellbore Marker.',
  `Missing` STRING COMMENT 'The geologic reason why a portion of material (typically a rock formation) is missing from the real world material/rock being measured, compared to what was expected based on offset wells. Examples: fault, unconformity, fold. This property corresponds to marker property type reference-data--MarkerPropertyType:MissingReason.',
  `GeologicalAge` STRING COMMENT 'Associated geological age',
  `work_product_component_WellboreMarkerSet_id` INT COMMENT 'Autocreated FK slot',
  `InterpretationID_id` INT COMMENT 'The optional relationship to a HorizonInterpretation, GeobodyBoundaryInterpretation or FaultInterpretation.',
  `MarkerTypeID_id` INT COMMENT 'Marker Type Reference Type. Possible values - Biostratigraphy, Lithostratigraphy, seismic, depth of well, sequence, flow unit',
  `FeatureTypeID_id` INT COMMENT 'Feature Type Reference Type. Possible values - Base, top, fault, salt, reef, sea floor'
)
USING iceberg
COMMENT 'The array of marker meta data in this set.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreMarkerSetMarkers');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreTrajectoryAvailableTrajectoryStationProperties` (
  `id` BIGINT NOT NULL,
  `Name` STRING COMMENT 'The name of the curve (e.g. column in a CSV document) as originally found. If absent The name of the TrajectoryStationPropertyType is intended to be used.',
  `work_product_component_WellboreTrajectory_id` INT COMMENT 'Autocreated FK slot',
  `TrajectoryStationPropertyTypeID_id` INT COMMENT 'The reference to a trajectory station property type - or if interpreted as channels, the curve or channel name type, identifying e.g. MD, Inclination, Azimuth. This is a relationship to a reference-data--TrajectoryStationPropertyType record id.',
  `StationPropertyUnitID_id` INT COMMENT 'Unit of Measure for the station properties of type TrajectoryStationPropertyType.'
)
USING iceberg
COMMENT 'A set of properties describing a trajectory station property which is available for this instance of a WellboreTrajectory.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreTrajectoryAvailableTrajectoryStationProperties');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WellboreWellboreCosts` (
  `id` BIGINT NOT NULL,
  `CostValue` DOUBLE COMMENT 'The cost value associated with the WellActivityPhaseType.',
  `master_data_Wellbore_id` INT COMMENT 'Autocreated FK slot',
  `ActivityTypeID_id` INT COMMENT 'The activity type, to which the Cost property is attributed to. The intended target reference-data type is WellActivityType; Wellbore:1.3.0 and Wellbore:1.4.0 used WellActivityPhaseType incorrectly.'
)
USING iceberg
COMMENT 'A cost value associated to a WellActivityPhaseType value.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WellboreWellboreCosts');

CREATE TABLE IF NOT EXISTS demo.`osdu`.`WorkProductLineageAssertions` (
  `id` BIGINT NOT NULL,
  `work_product_WorkProduct_id` INT COMMENT 'Autocreated FK slot',
  `LineageRelationshipType_id` INT COMMENT 'Used by LineageAssertion to describe the nature of the line of descent of a work product from a prior Resource, such as DIRECT, INDIRECT, REFERENCE.  It is not for proximity (number of nodes away), it is not to cover all the relationships in a full ontology or graph, and it is not to describe the type of activity that created the asserting WP.  LineageAssertion does not encompass a full provenance, process history, or activity model.'
)
USING iceberg
COMMENT 'LineageAssertion'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'WorkProductLineageAssertions');

