CREATE TABLE IF NOT EXISTS demo.`reference_data`.`AliasNameType` (
  `id` BIGINT NOT NULL,
  `AliasNameUniqueValueIndicator` BOOLEAN COMMENT 'Indicates whether the value for alias names of a given alias name type must be universally unique. \'Y\' indicates that there is a requirement for unique values. \'N\' indicates that there is no requirement for unique values.',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `Name` STRING COMMENT 'The name of the entity instance.',
  `InactiveIndicator` BOOLEAN COMMENT 'By default reference values are considered as \'active\'. An absent \'InactiveIndicator\' property value means the reference value is in active use. When \'InactiveIndicator\' is set true the reverence value is no longer in use and should no longer be offered as a choice.',
  `Description` STRING COMMENT 'The text which describes a NAME TYPE in detail.',
  `Code` STRING COMMENT 'The abbreviation or mnemonic for a reference type if defined. Example: WELL and WLBR.',
  `AttributionAuthority` STRING COMMENT 'Name of the authority, or organisation, which governs the entity value and from which it is sourced.',
  `AttributionPublication` STRING COMMENT 'Name, URL, or other identifier of the publication, or repository, of the attribution source organisation from which the entity value is sourced.',
  `AttributionRevision` STRING COMMENT 'The distinct instance of the attribution publication, by version number, sequence number, date of publication, etc., that was used for the entity value.',
  `CommitDate` TIMESTAMP COMMENT 'For reference values published and governed by OSDU: The date and time the record was committed into the OSDU member GitLab reference-values repository. The sole purpose of this date is to optimise the OSDU milestone upgrades. It allows the upgrade code to figure out whether or not the record must be PUT into reference value storage.',
  `AliasNameTypeClassID_id` INT COMMENT 'This supports the type of AliasName (such as Standard Identifier, System Identifier, and so on). AliasNameTypeClass is intended to be used to categorize alias name types by their general purpose, with values like "Standard Identifier", "System Identifier", and "Moniker". Combined with the AliasNameType, and DefinitionOrganisation one can define a complete context for a particular identifier or name. For example, a standard identifier of type Regulatory ID, from API, is the US standards regulatory ID; a standard identifier of type company ID, from BigOil, is BigOil\'s Standard ID; System Identifiers would be particular to systems of record, or other systems, and Monikers, things like display names, plot labels, etc.',
  `ResourceHomeRegionID_id` INT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` INT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` INT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` INT,
  `ExistenceKind_id` INT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` INT
)
USING iceberg
COMMENT 'Used to describe the type of name aliases.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'reference-data/AliasNameType');

