CREATE TABLE IF NOT EXISTS demo.`reference_data`.`CoordinateReferenceSystem` (
  `id` BIGINT NOT NULL,
  `CodeSpace` STRING COMMENT 'The namespace or authority name governing this CRS definition, e.g. EPSG for contents from the EPSG Geodetic Parameter Dataset.',
  `InformationSource` STRING COMMENT 'The InformationSource providing the CRS definition if different from AttributionAuthority.',
  `RevisionDate` TIMESTAMP COMMENT 'The revision date of this CRS.',
  `Kind` STRING COMMENT 'The kind of CRS, e.g. bound, compound, derived, engineering, geocentric, geographic 2D, geographic 3D, projected, vertical.',
  `CodeAsNumber` INT COMMENT 'The code as number as opposed to the Code defined as a string.',
  `CoordinateReferenceSystemType` STRING COMMENT 'The type of coordinate reference system. This is an enumeration of concrete sub-types.',
  `PersistableReference` STRING COMMENT 'Used for export and actionable instructions to a conversion/transformation engine. It is initially based on Esri well-known text (WKT). Eventually, when Esri WKT are convertible into ISO WKT and vice versa, the definition can be replaced by https://proj.org/schemas/v0.2/projjson.schema.json.',
  `OGCWellKnownText2` STRING COMMENT 'OGC WKT 2 (Well-Known Text 2) OGC Well Known Text (WKT) 2  representation of a Coordinate Reference System (CRS) or coordinate operation, intended for interoperability with geospatial libraries and external systems that consume OGC-compliant WKT2 definitions',
  `HorizontalCRS` STRING COMMENT 'The horizontal CRS reference of a CompoundCRS. Only populated for CoordinateReferenceSystemType==CompoundCRS.',
  `VerticalCRS` STRING COMMENT 'The vertical CRS reference of a CompoundCRS. Only populated for CoordinateReferenceSystemType==CompoundCRS.',
  `Transformation` STRING COMMENT 'The Transformation bound to the BaseCRS in a BoundCRS. Only populated for CoordinateReferenceSystemType==BoundCRS.',
  `Datum` STRING COMMENT 'The datum of this CRS. Only populated for CoordinateReferenceSystemType in [GeographicCRS, VerticalCRS, EngineeringCRS].',
  `DatumEnsemble` STRING COMMENT 'The DatumEnsemble for the CRS\'s datum. Only populated for GeographicCRS.',
  `Projection` STRING COMMENT 'The projection operation of a ProjectedCRS. Only populated for CoordinateReferenceSystemType==ProjectedCRS.',
  `BaseCRS` STRING COMMENT 'The base geographic CRS of this projected CRS. Only populated for CoordinateReferenceSystemType==ProjectedCRS.',
  `SourceCRS` STRING COMMENT 'The source CRS of a BoundCRS. Only populated for CoordinateReferenceSystemType==BoundCRS.',
  `TargetCRS` STRING COMMENT 'The target CRS of this bound CRS. Only populated for CoordinateReferenceSystemType==BoundCRS.',
  `CoordinateSystem` STRING COMMENT 'The coordinate system defining the dimension and individual axes used by the CRS.',
  `PreferredUsage` STRING COMMENT 'Scope and extent information about the described CRS.',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `Name` STRING COMMENT 'The name of the entity instance.',
  `InactiveIndicator` BOOLEAN COMMENT 'By default reference values are considered as \'active\'. An absent \'InactiveIndicator\' property value means the reference value is in active use. When \'InactiveIndicator\' is set true the reverence value is no longer in use and should no longer be offered as a choice.',
  `Description` STRING COMMENT 'The text which describes a NAME TYPE in detail.',
  `Code` STRING COMMENT 'The abbreviation or mnemonic for a reference type if defined. Example: WELL and WLBR.',
  `AttributionAuthority` STRING COMMENT 'Name of the authority, or organisation, which governs the entity value and from which it is sourced.',
  `AttributionPublication` STRING COMMENT 'Name, URL, or other identifier of the publication, or repository, of the attribution source organisation from which the entity value is sourced.',
  `AttributionRevision` STRING COMMENT 'The distinct instance of the attribution publication, by version number, sequence number, date of publication, etc., that was used for the entity value.',
  `CommitDate` TIMESTAMP COMMENT 'For reference values published and governed by OSDU: The date and time the record was committed into the OSDU member GitLab reference-values repository. The sole purpose of this date is to optimise the OSDU milestone upgrades. It allows the upgrade code to figure out whether or not the record must be PUT into reference value storage.',
  `HorizontalCRS_HorizontalCRSID_id` BIGINT,
  `VerticalCRS_VerticalCRSID_id` BIGINT,
  `Transformation_TransformationID_id` BIGINT,
  `BaseCRS_BaseCRSID_id` BIGINT,
  `SourceCRS_SourceCRSID_id` BIGINT,
  `TargetCRS_TargetCRSID_id` BIGINT,
  `CoordinateSystem_HorizontalAxisUnitID_id` BIGINT,
  `CoordinateSystem_VerticalAxisUnitID_id` BIGINT,
  `Wgs84Coordinates_id` BIGINT COMMENT 'The 2-dimensional bounding box derived from the extent (Polygon or MultiPolygon) based on WGS 84 (EPSG:4326). The schema of this substructure is identical to the GeoJSON FeatureCollection https://geojson.org/schema/FeatureCollection.json. The coordinate sequence follows GeoJSON standard, i.e. longitude, latitude. CoordinateReferenceSystems with an extent crossing the anti-meridian are represented by a MultiPolygon.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT
)
USING iceberg
COMMENT 'Used to describe any kind of coordinate reference system. The type is identified by CoordinateReferenceSystemType (used by the system) and Kind facing the end-user. The Code is according to OSDU standard a string, the EPSG standard number is available via the CodeAsNumber property. Description carries EPSG\'s Remark. AttributionAuthority carries EPSG\'s DataSource. AliasNames carry the EPSG Alias contents.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'reference-data/CoordinateReferenceSystem');

