CREATE TABLE IF NOT EXISTS demo.`reference_data`.`CoordinateTransformation` (
  `id` BIGINT NOT NULL,
  `CoordTfmVersion` STRING COMMENT 'The name of the transformation version or variant',
  `Variant` INT COMMENT 'The Transformation variant number.',
  `Accuracy` DOUBLE COMMENT 'The accuracy of the transformation expressed in meters.',
  `CodeSpace` STRING COMMENT 'The namespace or authority name governing this Transformation definition, e.g. EPSG for contents from the EPSG Geodetic Parameter Dataset.',
  `InformationSource` STRING COMMENT 'The InformationSource providing the Transformation definition if different from AttributionAuthority.',
  `RevisionDate` TIMESTAMP COMMENT 'The revision date of this Transformation.',
  `Kind` STRING COMMENT 'The kind of Transformation, e.g. Transformation, Concatenated Transformation.',
  `CodeAsNumber` INT COMMENT 'The code as number as opposed to the Code defined as a string.',
  `CoordinateTransformationType` STRING COMMENT 'The type of coordinate transformation. This is an enumeration of concrete sub-types. Transformation is a single operation between a source and a target geodetic CRS; ConcatenatedOperation is a chained set of Transformations.',
  `PersistableReference` STRING COMMENT 'Used for export and actionable instructions to a conversion/transformation engine. It is initially based on Esri well-known text (WKT). Eventually, when Esri WKT are convertible into ISO WKT and vice versa, the definition can be replaced by https://proj.org/schemas/v0.2/projjson.schema.json.',
  `OGCWellKnownText2` STRING COMMENT 'OGC WKT 2 (Well-Known Text 2) OGC Well Known Text (WKT) 2  representation of a Coordinate Reference System (CRS) or coordinate operation, intended for interoperability with geospatial libraries and external systems that consume OGC-compliant WKT2 definitions',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `Name` STRING COMMENT 'The name of the entity instance.',
  `InactiveIndicator` BOOLEAN COMMENT 'By default reference values are considered as \'active\'. An absent \'InactiveIndicator\' property value means the reference value is in active use. When \'InactiveIndicator\' is set true the reverence value is no longer in use and should no longer be offered as a choice.',
  `Description` STRING COMMENT 'The text which describes a NAME TYPE in detail.',
  `Code` STRING COMMENT 'The abbreviation or mnemonic for a reference type if defined. Example: WELL and WLBR.',
  `AttributionAuthority` STRING COMMENT 'Name of the authority, or organisation, which governs the entity value and from which it is sourced.',
  `AttributionPublication` STRING COMMENT 'Name, URL, or other identifier of the publication, or repository, of the attribution source organisation from which the entity value is sourced.',
  `AttributionRevision` STRING COMMENT 'The distinct instance of the attribution publication, by version number, sequence number, date of publication, etc., that was used for the entity value.',
  `CommitDate` TIMESTAMP COMMENT 'For reference values published and governed by OSDU: The date and time the record was committed into the OSDU member GitLab reference-values repository. The sole purpose of this date is to optimise the OSDU milestone upgrades. It allows the upgrade code to figure out whether or not the record must be PUT into reference value storage.',
  `Wgs84Coordinates_id` BIGINT COMMENT 'The 2-dimensional bounding box derived from the extent (Polygon or MultiPolygon) based on WGS 84 (EPSG:4326). The schema of this substructure is identical to the GeoJSON FeatureCollection https://geojson.org/schema/FeatureCollection.json. The coordinate sequence follows GeoJSON standard, i.e. longitude, latitude. CoordinateTransformations with an extent crossing the anti-meridian are represented by a MultiPolygon.',
  `Method_id` BIGINT COMMENT 'The Transformation method; "Concatenated" for CoordinateTransformationType == ConcatenatedOperation; EPSG method code and name for CoordinateTransformationType == Transformation.',
  `SourceCRS_id` BIGINT COMMENT 'The source CRS of the Transformation.',
  `TargetCRS_id` BIGINT COMMENT 'The target CRS of this Transformation.',
  `PreferredUsage_id` BIGINT COMMENT 'Scope and extent information about the described transformation.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT
)
USING iceberg
COMMENT 'Used to describe a coordinate operation between two geodetic CRSs. The type is identified by CoordinateTransformationType (used by the system) and Kind facing the end-user. The Code is according to OSDU standard a string, the EPSG standard number is available via the CodeAsNumber property. Description carries EPSG\'s Remark. AttributionAuthority carries EPSG\'s DataSource. AliasNames carry the EPSG Alias contents.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'reference-data/CoordinateTransformation');

