  `DatePublished` TIMESTAMP COMMENT 'The UTC date time and date of the document publication',
  `DateModified` TIMESTAMP COMMENT 'The UTC date time and date of the document when it was last modified',
  `DateReviewDue` TIMESTAMP COMMENT 'Date when a next review/revision of the document is due.',
  `DateIssued` TIMESTAMP COMMENT 'Formal sign-off / approval date (may be different from DatePublished)',
  `RetentionPeriod` DOUBLE COMMENT 'Number of years the document needs to be retained after the last modification (see data.DataModified property).',
  `Summary` STRING COMMENT 'Summary of document contents',
  `TableOfContents` STRING COMMENT 'Table of contents of the document',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `IsExtendedLoad` BOOLEAN COMMENT 'A flag that indicates if the work product component is undergoing an extended load.  It reflects the fact that the work product component is in an early stage and may be updated before finalization.',
  `IsDiscoverable` BOOLEAN COMMENT 'A flag that indicates if the work product component is searchable, which means covered in the search index.',
  `Name` STRING COMMENT 'Name',
  `Description` STRING COMMENT 'Description.  Summary of the work product component.  Not the same as Remark which captures thoughts of creator about the wpc.',
  `CreationDateTime` TIMESTAMP COMMENT 'Date that a resource (work  product component here) is formed outside of OSDU before loading (e.g. publication date).',
  `SubmitterName` STRING COMMENT 'Name of the person that first submitted the work product component to OSDU.',
  `ProducedByOrganisationID_id` INT COMMENT 'The organisation or institution that produced this document',
  `ProducedForOrganisationID_id` INT COMMENT 'The organisation or institution that this document was produced this for',
  `ResourceHomeRegionID_id` INT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` INT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` INT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` INT,
  `ExistenceKind_id` INT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` INT,
  `SpatialPoint_id` INT COMMENT 'A centroid point that reflects the locale of the content of the work product component (location of the subject matter).',
  `SpatialArea_id` INT COMMENT 'A polygon boundary that reflects the locale of the content of the work product component (location of the subject matter).'
)
USING iceberg
COMMENT 'A document can be any document that is required to be stored in an electronic format. Examples of this could be daily drilling reports, drilling schematics, or material quality analysis reports.'
