CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`Document_TaxonomyIDs` (
  `work_product_component_Document_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `TaxonomyIDs_id` INT NOT NULL COMMENT 'The Document Taxonomy provides a structured taxonomy for categorising document types. This taxonomy adheres to a consistent naming convention of a DISCIPLINE followed by a document type, using a dot-based nomenclature e.g., <DISCIPLINE>.<Document Type>. This creates a two level hierarchy of the document type to support classification and search. This a recommended property. A Document may have one or more document types (for example, End of Well Reports may contain a wide range of information).'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/Document_TaxonomyIDs');

CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`PPFGDataset` (
  `id` BIGINT NOT NULL,
  `RecordDate` TIMESTAMP COMMENT 'The date that the PPFG data set was created by the PPFG practitioner or contractor',
  `Comment` STRING COMMENT 'Open comments from the calculation team',
  `PrimaryReferenceCurveID` STRING COMMENT 'ID of the PPFG curve that is the primary reference or index. Derived from the PPFG curve ID',
  `PrimaryReferenceType` STRING COMMENT 'The type of the primary reference, for example \'TVDSS\',  \'MD\' , \'TWT\'',
  `AbsentValueCharacters` STRING COMMENT 'The characters that represent absent curve values in this data set, for example  \'-999\', \'NULL\', \'0\', etc. Typically for legacy data',
  `GaugeType` STRING COMMENT 'Free text to describe the type of gauge used for the pressure measurement',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `IsExtendedLoad` BOOLEAN COMMENT 'A flag that indicates if the work product component is undergoing an extended load.  It reflects the fact that the work product component is in an early stage and may be updated before finalization.',
  `IsDiscoverable` BOOLEAN COMMENT 'A flag that indicates if the work product component is searchable, which means covered in the search index.',
  `Name` STRING COMMENT 'Name',
  `Description` STRING COMMENT 'Description.  Summary of the work product component.  Not the same as Remark which captures thoughts of creator about the wpc.',
  `CreationDateTime` TIMESTAMP COMMENT 'Date that a resource (work  product component here) is formed outside of OSDU before loading (e.g. publication date).',
  `SubmitterName` STRING COMMENT 'Name of the person that first submitted the work product component to OSDU.',
  `WellID_id` BIGINT COMMENT 'ID from the Well where the PPFG Work Product Component was recorded',
  `WellboreID_id` BIGINT COMMENT 'ID from the Wellbore where the PPFG Work Product Component was recorded',
  `ContextTypeID_id` BIGINT COMMENT 'ID that reflects the context of the PPFG  data set, for example \'Pre-Drill\' or \'Post-Drill\'',
  `ServiceCompanyID_id` BIGINT COMMENT 'ID of the service Company that acquired the PPFG',
  `ReferenceWellTrajectoryID_id` BIGINT COMMENT 'Id of the Reference WellTrajectory used for TVD\'s calculation',
  `TectonicSetting_id` BIGINT COMMENT 'Tectonic Scenario Setting for Planning and Pore Pressure Practitioners. Built into interpretive curves. Can be, for example \'Strike Slip\'',
  `VerticalMeasurement_id` BIGINT COMMENT 'The Vertical Measurement for the Wellbore identified which defines the vertical reference pressure datum for the related PPFG curves in this data set. The pressure datum is used to calculate the average pressure gradient in',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialPoint_id` BIGINT COMMENT 'A centroid point that reflects the locale of the content of the work product component (location of the subject matter).',
  `SpatialArea_id` BIGINT COMMENT 'A polygon boundary that reflects the locale of the content of the work product component (location of the subject matter).'
)
USING iceberg
COMMENT 'Pore Pressure and Fracture (Pressure) Gradient (PPFG) data describes the predicted (Pre-drill) and actual (Post-drill) depth-related variations in overburden stress, pore pressure, fracture pressure and minimum principal stress within a wellbore and conveys the range of uncertainty in these values given various plausible geological scenarios. PPFG predictions are fundamental inputs for well design and construction and estimates of pore and fracture pressure are typically provided to the well planning and execution teams.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/PPFGDataset');

