CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`WellLog` (
  `id` BIGINT NOT NULL,
  `NullValue` STRING COMMENT 'The value used within curves to indicate there is no data over specific depth ranges.',
  `TopMeasuredDepth` DOUBLE,
  `BottomMeasuredDepth` DOUBLE,
  `LogSource` STRING,
  `LogActivity` STRING,
  `LogRun` STRING,
  `LogVersion` STRING,
  `LoggingService` STRING,
  `ToolStringDescription` STRING,
  `LoggingDirection` STRING,
  `PassNumber` INT,
  `ActivityType` STRING COMMENT 'General method or circumstance of logging - MWD, completion, etc. This is free text string. Use the Use Well Log Acquisition schema `LogRuns[].ConveyanceMethodID` property where possible to capture the conveyance method.',
  `DrillingFluidProperty` STRING,
  `HoleTypeLogging` STRING,
  `VerticalMeasurementID` STRING,
  `FrameIdentifier` STRING COMMENT 'Required for complex DLIS format files defined by having multiple Logical Files and/or multiple Frames.  The Frame Identifier is a numerical attribute that represents the interval spacing of the data within the frame.',
  `LogicalFileIdentifier` STRING COMMENT 'Required for complex DLIS format files defined by having multiple Logical Files and/or multiple Frames.  The Logical File Identifier is a numerical attribute that represents the collection of a series of data groups (e.g. logging passes within a single logging run), and each Logical File may contain one or multiple Frames.',
  `SamplingInterval` DOUBLE COMMENT 'For regularly sampled curves this property holds the sampling interval. For non regular sampled data this property is not set. This property can be captured here for composite log sets and within the Well Log Acquisition schema for raw data for each Log Run using the `LogRun[].SamplingInterval`. The IsRegular flag indicates whether SamplingInterval is required.',
  `ReferenceCurveID` STRING COMMENT 'The name of the curve that holds the primary index (reference) values.',
  `SamplingStart` DOUBLE COMMENT 'The start value/first value of the ReferenceCurveID, typically the smallest value that represents the depth or time of the logging. At Well Log level, this is designed to represent the smallest sampling interval of any and all individual logging runs and passes.',
  `SamplingStop` DOUBLE COMMENT 'The stop value/last value of the ReferenceCurveID, typically the largest value that represents depth or time of the logging. At the Well Log level, this is designed to represent the largest sampling interval of any and all individual logging runs and passes.',
  `ZeroTime` TIMESTAMP COMMENT 'Optional time reference for (calendar) time logs. The ISO date time string representing zero time. Not to be confused with seismic travel time zero. The latter is defined by SeismicReferenceDatum.',
  `IsRegular` BOOLEAN COMMENT 'Boolean property indicating the sampling mode of the ReferenceCurveID. True means all reference curve values are regularly spaced (see SamplingInterval); false means irregular or discrete sample spacing.',
  `LogRemark` STRING,
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `IsExtendedLoad` BOOLEAN COMMENT 'A flag that indicates if the work product component is undergoing an extended load.  It reflects the fact that the work product component is in an early stage and may be updated before finalization.',
  `IsDiscoverable` BOOLEAN COMMENT 'A flag that indicates if the work product component is searchable, which means covered in the search index.',
  `Name` STRING COMMENT 'Name',
  `Description` STRING COMMENT 'Description.  Summary of the work product component.  Not the same as Remark which captures thoughts of creator about the wpc.',
  `CreationDateTime` TIMESTAMP COMMENT 'Date that a resource (work  product component here) is formed outside of OSDU before loading (e.g. publication date).',
  `SubmitterName` STRING COMMENT 'Name of the person that first submitted the work product component to OSDU.',
  `WellboreID_id` BIGINT COMMENT 'The Wellbore where the Well Log Work Product Component was recorded',
  `WellLogClassID_id` BIGINT COMMENT 'Identifies the WellLogClass or business domain of this Well Log and associated set of curves. Examples include, Petrophysical Logs, Drilling Logs and Production Logs.',
  `WellLogTypeID_id` BIGINT COMMENT 'Well Log Type short Description such as Raw; Evaluated; Composite;....',
  `ServiceCompanyID_id` BIGINT,
  `WellboreFluidTypeID_id` BIGINT,
  `ConveyanceMethodID_id` BIGINT,
  `VerticalMeasurement_id` BIGINT COMMENT 'The vertical measurement reference for the log curves, which defines the vertical reference datum for the logged depths. Either VerticalMeasurement or VerticalMeasurementID are populated.',
  `SamplingDomainTypeID_id` BIGINT COMMENT 'The along wellbore reference value for the Well Log data (e.g. Measured Depth, True Vertical Depth, One-way Travel Time, Calendar Time).',
  `CompanyID_id` BIGINT,
  `SeismicReferenceElevation_id` BIGINT COMMENT 'Populated only if the WellLog represents time-depth relationships or check shots. It is expressed via the standard AbstractFacilityVerticalMeasurement. The following properties are expected to be present: VerticalMeasurementPathID (typically elevation), VerticalMeasurementTypeID as SeismicReferenceDatum, VerticalMeasurement holding the offset to either the VerticalCRSID or the chained VerticalReferenceID in the parent Wellbore.',
  `LogServiceDateInterval_id` BIGINT COMMENT 'An interval built from two nested values : StartDate and EndDate. It applies to the whole log services and may apply to composite logs as [start of the first run job] and [end of the last run job]Log Service Date',
  `WellLogAcquisitionDetails_id` BIGINT COMMENT 'The Well Log Acquisition details object captures Information relevant to the well log acquisition, such as the specific acquisition job, log runs and log passes that this  well log information derives from.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialPoint_id` BIGINT COMMENT 'A centroid point that reflects the locale of the content of the work product component (location of the subject matter).',
  `SpatialArea_id` BIGINT COMMENT 'A polygon boundary that reflects the locale of the content of the work product component (location of the subject matter).'
)
USING iceberg
COMMENT 'A well log is a data type that correlates a particular measurement or multiple measurements in a wellbore against depth and/or time within that wellbore. When plotted visually, well logs are typically long line graphs (called "curves") but may sometimes be discrete points or intervals. This schema object is intended for digital well logs, not raster log files or raster calibration files, but may be used for the latter in the absence of a defined OSDU schema for these use cases.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/WellLog');

