CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`WellboreTrajectory` (
  `id` BIGINT NOT NULL,
  `TopDepthMeasuredDepth` DOUBLE NOT NULL COMMENT 'Measured depth in the wellbore where the directional survey starts. This should equal the minimum station measured depth for this directional survey, regardless of whether the surveyed station represents an actual surveyed MD or not.',
  `ActiveIndicator` BOOLEAN COMMENT 'A flag indicating if the survey is currently active or valid within his lifecycle stage, not necessarily the definitive survey.',
  `SurveyType` STRING COMMENT 'The type of this directional survey.  For example a "Directional Survey" where MD, Inclination and Azimuth are all measured or a "Position Log" where Inclination and Azimuth are both null and only MD, TVD and X/Y Offsets are available) - or "Full Survey" where everything is fully filled-up, depth-inclination-azimuth.',
  `AcquisitionDate` TIMESTAMP COMMENT 'The date that the survey data was acquired on the field.',
  `AcquisitionRemark` STRING COMMENT 'Remarks related to acquisition context which is not the same as Description which is a summary of the work-product-component.',
  `SurveyReferenceIdentifier` STRING COMMENT 'Unique or Distinctive Survey Reference Number, Job Number, File Number, Identifier, Label, Name, etc. as indicated on a directional survey report, file, etc.  Use this attribute to allow correlation of the data in this Directional Survey back to the original source document, file, etc.',
  `SurveyVersion` STRING COMMENT 'The version of the wellbore survey deliverable received from the service provider - as given by this provider',
  `ExtrapolatedMeasuredDepth` DOUBLE COMMENT 'The measured depth to which the survey segment was extrapolated.',
  `ExtrapolatedMeasuredDepthRemark` STRING COMMENT 'Comment/Annotation made to WellboreTrajectory describing the projected MD Base or Bottomhole, e.g., listing the Depth Reference Name, Elevation and Bottomhole MD. This can be used for comparison against the survey at a later date.',
  `BaseDepthMeasuredDepth` DOUBLE NOT NULL COMMENT 'Measured depth within the wellbore of the LAST surveyed station with recorded data.  If a stored survey has been extrapolated to a deeper depth than the last surveyed station then that is the extrapolated measured depth and not the survey base depth.',
  `TieMeasuredDepth` DOUBLE COMMENT 'Tie-point depth measured along the wellbore from the measurement reference datum to the survey station - where tie point is the place on the originating survey where the current survey intersect it.',
  `TieTrueVerticalDepth` DOUBLE COMMENT 'True Vertical Depth of the TieMeasuredDepth',
  `AppliedOperationsDateTime` TIMESTAMP COMMENT 'Date/time when the directional Survey QA/QC was performed.',
  `AppliedOperationsUser` STRING COMMENT 'Name of Borehole Survey specialist who performed the QA/QC work',
  `AppliedOperationsRemarks` STRING COMMENT 'Any comments captured by the Borehole Survey specialist when performing the QA/QC work.',
  `StartDateTime` TIMESTAMP COMMENT 'The date and time capturing when the first survey station was measured.',
  `EndDateTime` TIMESTAMP COMMENT 'The date and time capturing when the last survey station was measured.',
  `SurfaceGridConvergence` DOUBLE COMMENT 'The Grid Convergence angle computed at the surface position, which was used for the WellboreTrajectory True North to Grid North Azimuths corrections. Only populated for projected CRSs. Recommended sign convention: Gauss-Bomford.',
  `SurfaceScaleFactor` DOUBLE COMMENT 'The Scale Factor computed for the wellbore\'s surface position used for calculating projected Map Coordinates from survey data in WellboreTrajectory.',
  `Tortuosity` DOUBLE COMMENT 'The calculated average Tortuosity for the WellboreTrajectory.',
  `VerticalSectionAzimuth` DOUBLE COMMENT 'Azimuth angle used for vertical section projection/computations of the survey stations.',
  `MagneticFieldCalculationDate` TIMESTAMP COMMENT 'Date against Geomagnetic field calculated',
  `MagneticDeclinationUsed` DOUBLE COMMENT 'Calculated magnetic declination used to correct a Magnetic North referenced azimuth to a True North azimuth. Magnetic declination angles are measured positive clockwise from True North to Magnetic North (or negative in the anti-clockwise direction). To convert a Magnetic azimuth to a True North azimuth, the magnetic declination should be added. Starting value if stations have individual values.',
  `MagneticDeclinationUncertainty` DOUBLE COMMENT 'Survey tool declination uncertainty.',
  `MagneticDipAngleReference` DOUBLE COMMENT 'Calculated magnetic dip angle theoretical / reference value.',
  `MagneticDipAngleUncertainty` DOUBLE COMMENT 'Survey tool dip angle uncertainty.',
  `TotalMagneticFieldStrength` DOUBLE COMMENT 'Calculated geomagnetic field theoretical/reference value.',
  `TotalMagneticFieldStrengthUncertainty` DOUBLE COMMENT 'Survey tool magnetic uncertainty.',
  `TotalGravityFieldStrength` DOUBLE COMMENT 'Calculated total gravity field.',
  `TotalGravityFieldStrengthUncertainty` DOUBLE COMMENT 'Survey tool gravity uncertainty.',
  `VerticalSectionOriginNS` DOUBLE COMMENT 'Vertical Section Origin North / -South relative to the Well SHL Projected CRS 0, 0 origin. 0 where Vertical Section Projection originates from the wellhead.',
  `VerticalSectionOriginEW` DOUBLE COMMENT 'Vertical Section Origin East / -West relative to the Well SHL Projected CRS 0, 0 origin. 0 where Vertical Section Projection originates from the wellhead.',
  `IsDefinitive` BOOLEAN COMMENT 'True indicates that this trajectory is definitive for this wellbore as provided by the survey contractor. False or not given indicates otherwise. There can only be one trajectory per wellbore with definitive=true and it must define the geometry of the whole wellbore (surface to TD). The definitive trajectory may represent a composite of survey data from one or more other trajectories.',
  `IsMemory` BOOLEAN COMMENT 'Is trajectory a result of a memory dump from a tool?',
  `IsFinal` BOOLEAN COMMENT 'From the survey contractors perspective providing the survey to the Operator is the trajectory final (true) or intermediate/preliminary (false)? Does not mean that the trajectory cannot be worked on further by the Operator.',
  `Source` STRING COMMENT 'The entity that produced the record, or from which it is received; could be an organization, agency, system, internal team, or individual. For informational purposes only, the list of sources is not governed.',
  `IsExtendedLoad` BOOLEAN COMMENT 'A flag that indicates if the work product component is undergoing an extended load.  It reflects the fact that the work product component is in an early stage and may be updated before finalization.',
  `IsDiscoverable` BOOLEAN COMMENT 'A flag that indicates if the work product component is searchable, which means covered in the search index.',
  `Name` STRING COMMENT 'Name',
  `Description` STRING COMMENT 'Description.  Summary of the work product component.  Not the same as Remark which captures thoughts of creator about the wpc.',
  `CreationDateTime` TIMESTAMP COMMENT 'Date that a resource (work  product component here) is formed outside of OSDU before loading (e.g. publication date).',
  `SubmitterName` STRING COMMENT 'Name of the person that first submitted the work product component to OSDU.',
  `ServiceCompanyID_id` BIGINT COMMENT 'Name of the Survey Company.',
  `WellboreID_id` BIGINT NOT NULL COMMENT 'A unique name, code or number designated to the Wellbore.',
  `AzimuthReferenceType_id` BIGINT COMMENT 'The North reference of the trajectory used to define the azimuth angular measurement values. For example, True North, Grid North, Magnetic North.',
  `CalculationMethodType_id` BIGINT COMMENT 'Calculation Method used to calculate the Wellpath Trajectory from the directional survey data including TVD, X OFFSET, Y OFFSET and DOG LEG SEVERITY. Examples include Minimum Curvature, Radius of Curvature, Balanced Tangential, etc.',
  `ProjectedCRSID_id` BIGINT COMMENT 'Coordinate Reference System defining the Projection of the station EASTING and NORTHING values. If  type is "Grid North" and EASTING and NORTHING attributes are stored, clearly identifying their projection is required.',
  `GeographicCRSID_id` BIGINT COMMENT 'Coordinate Reference System defining the Geodetic Datum of the station LATITUDE and LONGITUDE values. If LATITUDE and LONGITUDE attributes are stored, clearly identifying their Datum is required.',
  `SurveyToolTypeID_id` BIGINT COMMENT 'The type of tool or equipment used to acquire this Directional Survey.  For example, gyroscopic, magnetic, MWD, TOTCO, acid bottle, etc. Follow OWSG reference data and support the ISCWSA survey tool definitions.',
  `VerticalMeasurement_id` BIGINT NOT NULL COMMENT 'References an entry in the Vertical Measurement array for the Wellbore identified by WellboreID, which defines the vertical reference datum for all survey station measured depths.',
  `CompanyID_id` BIGINT COMMENT 'The relationship to company who engaged the service company (ServiceCompanyID) to perform the surveying.',
  `GeoMagneticModelID_id` BIGINT COMMENT 'Geomagnetic Model Name including the applicable year used to calculate Geomagnetic field for a given date, coordinate and measured depth (when calculated down the wellbore).',
  `GravityModelID_id` BIGINT COMMENT 'Identifier of the Gravity Model in use for the survey.',
  `ResourceHomeRegionID_id` BIGINT COMMENT 'The name of the home [cloud environment] region for this OSDU resource object.',
  `ResourceCurationStatus_id` BIGINT COMMENT 'Describes the current Curation status.',
  `ResourceLifecycleStatus_id` BIGINT COMMENT 'Describes the current Resource Lifecycle status.',
  `ResourceSecurityClassification_id` BIGINT,
  `ExistenceKind_id` BIGINT COMMENT 'Where does this data resource sit in the cradle-to-grave span of its existence?',
  `TechnicalAssuranceID_id` BIGINT,
  `SpatialPoint_id` BIGINT COMMENT 'A centroid point that reflects the locale of the content of the work product component (location of the subject matter).',
  `SpatialArea_id` BIGINT COMMENT 'A polygon boundary that reflects the locale of the content of the work product component (location of the subject matter).'
)
USING iceberg
COMMENT 'Work Product Component describing an individual instance of a wellbore trajectory data object. Also called a directional or deviation survey, wellbore trajectory is data that is used to calculate the position and spatial uncertainty of a planned or actual wellbore in 2-dimensional and 3-dimensional space.'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/WellboreTrajectory');

CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`WellboreTrajectory_AppliedOperations` (
  `work_product_component_WellboreTrajectory_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `AppliedOperations` STRING NOT NULL COMMENT 'The audit trail of operations applied to the station coordinates from the original state to the current state. The list may contain operations applied prior to ingestion as well as the operations applied to produce the Wgs84Coordinates. The text elements refer to ESRI style CRS and Transformation names, which may have to be translated to EPSG standard names.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/WellboreTrajectory_AppliedOperations');

