CREATE TABLE IF NOT EXISTS demo.`work_product_component`.`WellboreTrajectory_DDMSDatasets` (
  `work_product_component_WellboreTrajectory_id` INT NOT NULL COMMENT 'Autocreated FK slot',
  `DDMSDatasets` STRING NOT NULL COMMENT 'An array of references to content in Domain Data Management Services represented by this work-product-component. The references are formed as URI following https://www.rfc-editor.org/rfc/rfc3986#page-16. This property is exclusively populated by DDMSs. If a work-product-component is represented in more than one DDMS, DDMSs are obliged to find the specific reference by inspecting the URI\'s authority values matching the DDMS id.'
)
USING iceberg
COMMENT 'None'
TBLPROPERTIES ('format-version' = '2', 'osdu.sourceTable' = 'work-product-component/WellboreTrajectory_DDMSDatasets');

